SINA.papers = (SINA.papers || []).concat([{"id": "y1-anat1-sina-mock", "subject": "anat1", "title": "Sina mock exam: Anatomy 1", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering the upper limb and the thorax. One answer per question, each with a short explanation.", "questions": [{"q": "The anatomical position is defined by:", "options": ["Standing upright, palms facing backward", "Lying supine, palms facing the body", "Standing upright, upper limbs by the sides, palms facing forward", "Sitting, head facing forward"], "answer": 2, "why": "Erect, eyes forward, upper limbs at the sides with palms anterior, feet together.", "slides": [{"src": "files/slides/anat1-intro/21.jpg", "lec": "Introduction to anatomy", "n": 21}]}, {"q": "Regarding the clavicle:", "options": ["It is the only bony link between the upper limb and the axial skeleton", "Its lateral end articulates with the manubrium", "Its medial end articulates with the acromion", "It has no medullary cavity and is never fractured"], "answer": 0, "why": "Medial end = sternoclavicular joint; lateral end = acromioclavicular joint. It is the most commonly fractured bone.", "slides": [{"src": "files/slides/anat1-thorax-osteology/15.jpg", "lec": "Thorax part 2: osteology", "n": 15}]}, {"q": "The surgical neck of the humerus is closely related to:", "options": ["The axillary nerve and posterior circumflex humeral artery", "The ulnar nerve", "The median nerve", "The radial nerve"], "answer": 0, "why": "Surgical neck fractures endanger the axillary nerve; mid-shaft fractures endanger the radial nerve (radial groove).", "slides": [{"src": "files/slides/anat1-scapular/06.jpg", "lec": "The scapular region and deltoid", "n": 6}]}, {"q": "Which muscle is NOT part of the rotator cuff?", "options": ["Teres major", "Infraspinatus", "Subscapularis", "Supraspinatus"], "answer": 0, "why": "SITS: supraspinatus, infraspinatus, teres minor, subscapularis. Teres major is not a cuff muscle.", "slides": [{"src": "files/slides/anat1-scapular/04.jpg", "lec": "The scapular region and deltoid", "n": 4}]}, {"q": "The deltoid muscle is innervated by:", "options": ["The axillary nerve", "The suprascapular nerve", "The musculocutaneous nerve", "The radial nerve"], "answer": 0, "why": "Axillary nerve (C5-C6) supplies deltoid and teres minor.", "slides": [{"src": "files/slides/anat1-scapular/04.jpg", "lec": "The scapular region and deltoid", "n": 4}]}, {"q": "The boundaries of the axilla include all of the following EXCEPT:", "options": ["Brachioradialis on the lateral wall", "Serratus anterior on the medial wall", "Pectoralis major in the anterior wall", "Subscapularis in the posterior wall"], "answer": 0, "why": "Lateral wall = intertubercular sulcus of the humerus; brachioradialis is a forearm muscle."}, {"q": "The anterior compartment of the arm contains:", "options": ["Pronator teres and supinator", "Biceps brachii, brachialis and coracobrachialis", "Brachioradialis and anconeus", "Triceps brachii and the radial nerve"], "answer": 1, "why": "Anterior arm = biceps, brachialis, coracobrachialis, all supplied by the musculocutaneous nerve.", "slides": [{"src": "files/slides/anat1-surface-joints/10.jpg", "lec": "Surface anatomy and joints of the", "n": 10}]}, {"q": "The content of the cubital fossa from lateral to medial is:", "options": ["Median nerve, brachial artery, biceps tendon", "Brachial artery, biceps tendon, median nerve", "Biceps tendon, brachial artery, median nerve", "Radial nerve, median nerve, biceps tendon"], "answer": 2, "why": "Lateral to medial: biceps tendon, brachial artery, median nerve (TAN).", "slides": [{"src": "files/slides/anat1-surface-joints/19.jpg", "lec": "Surface anatomy and joints of the", "n": 19}]}, {"q": "The ulnar nerve passes:", "options": ["Anterior to the lateral epicondyle", "Through the carpal tunnel", "Through the cubital fossa with the median nerve", "Posterior to the medial epicondyle"], "answer": 3, "why": "It runs behind the medial epicondyle (the 'funny bone') and enters the hand through Guyon's canal, not the carpal tunnel.", "slides": [{"src": "files/slides/anat1-cubital-fold/04.jpg", "lec": "The cubital fold (antecubital fossa)", "n": 4}]}, {"q": "Which structure passes through the carpal tunnel?", "options": ["Ulnar nerve", "Median nerve", "Ulnar artery", "Palmaris longus tendon"], "answer": 1, "why": "Carpal tunnel: median nerve + 9 tendons (FDS x4, FDP x4, FPL). Ulnar nerve and artery and palmaris longus pass superficial to the flexor retinaculum.", "slides": [{"src": "files/slides/anat1-hand-vessels-nerves/03.jpg", "lec": "Vascularisation and innervation of", "n": 3}]}, {"q": "The thenar muscles are mostly innervated by:", "options": ["The recurrent branch of the median nerve", "The radial nerve", "The anterior interosseous nerve", "The deep branch of the ulnar nerve"], "answer": 0, "why": "Abductor pollicis brevis, opponens pollicis and the superficial head of flexor pollicis brevis = recurrent median branch.", "slides": [{"src": "files/slides/anat1-hand-vessels-nerves/03.jpg", "lec": "Vascularisation and innervation of", "n": 3}]}, {"q": "The anatomical snuffbox contains:", "options": ["The ulnar artery", "The median nerve", "The basilic vein", "The radial artery"], "answer": 3, "why": "Its floor holds the scaphoid; the radial artery crosses it."}, {"q": "The sternal angle (of Louis):", "options": ["Marks the beginning of the abdominal aorta", "Is the junction between the body and the xiphoid process", "Lies at the level of the T10 vertebra", "Marks the articulation of the 2nd costal cartilage"], "answer": 3, "why": "Manubriosternal joint, level of rib 2 and the T4/T5 disc; arch of the aorta begins and ends there.", "slides": [{"src": "files/slides/anat1-thorax-overview/41.jpg", "lec": "Thorax part 1: overview", "n": 41}]}, {"q": "True ribs are:", "options": ["Ribs 1 to 10", "Ribs 11 and 12", "Ribs 8 to 10", "Ribs 1 to 7"], "answer": 3, "why": "Ribs 1-7 attach directly to the sternum by their own costal cartilage; 8-10 are false; 11-12 are floating.", "slides": [{"src": "files/slides/anat1-thorax-osteology/19.jpg", "lec": "Thorax part 2: osteology", "n": 19}]}, {"q": "The intercostal neurovascular bundle runs:", "options": ["Between the external intercostal muscle and the skin", "In the middle of the intercostal space", "In the costal groove, along the inferior border of the rib above", "Along the upper border of the rib below"], "answer": 2, "why": "VAN (vein, artery, nerve) from above downward, in the costal groove; needles are inserted just above the rib below.", "slides": [{"src": "files/slides/anat1-thorax-osteology/21.jpg", "lec": "Thorax part 2: osteology", "n": 21}]}, {"q": "The diaphragm is innervated by:", "options": ["The vagus nerve", "The sympathetic trunk", "The phrenic nerve (C3-C5)", "The intercostal nerves only"], "answer": 2, "why": "'C3, 4, 5 keeps the diaphragm alive' (motor supply).", "slides": [{"src": "files/slides/anat1-thorax-myology/24.jpg", "lec": "Thorax part 3: myology", "n": 24}]}, {"q": "The inferior vena cava passes through the diaphragm at the level of:", "options": ["L2", "T10", "T8", "T12"], "answer": 2, "why": "IVC T8, oesophagus T10, aorta T12.", "slides": [{"src": "files/slides/anat1-thorax-overview/22.jpg", "lec": "Thorax part 1: overview", "n": 22}]}, {"q": "The right coronary artery usually supplies:", "options": ["The sinoatrial and atrioventricular nodes", "The anterior two-thirds of the interventricular septum", "The left atrium only", "Mainly the left ventricle"], "answer": 0, "why": "In most people the RCA supplies the SA (≈60%) and AV (≈80%) nodes; the LAD supplies the anterior septum.", "slides": [{"src": "files/slides/anat1-heart/27.jpg", "lec": "Thorax part 5: the heart", "n": 27}]}, {"q": "The right lung has:", "options": ["Three lobes and one fissure", "Two lobes and one fissure", "Two lobes and a cardiac notch", "Three lobes and two fissures"], "answer": 3, "why": "Right: superior, middle, inferior lobes, oblique + horizontal fissures. Left: two lobes, cardiac notch and lingula.", "slides": [{"src": "files/slides/anat1-respiratory/09.jpg", "lec": "Thorax part 8: lungs and respiratory", "n": 9}]}, {"q": "The superior mediastinum contains:", "options": ["The heart and pericardium", "The arch of the aorta, the thymus and the brachiocephalic veins", "The inferior vena cava", "The descending thoracic aorta below T4 only"], "answer": 1, "why": "Superior mediastinum (above the T4/T5 plane): thymus, great veins, aortic arch and its branches, trachea, oesophagus, nerves.", "slides": [{"src": "files/slides/anat1-aorta/02.jpg", "lec": "Thorax parts 6-7: great vessels and", "n": 2}]}]}, {"id": "y1-anat2-sina-mock", "subject": "anat2", "title": "Sina mock exam: Anatomy 2", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering the abdomen, pelvis and perineum. One answer per question, each with a short explanation.", "questions": [{"q": "The inguinal canal:", "options": ["Has the external oblique aponeurosis as its posterior wall", "Lies below the inguinal ligament", "Runs from the deep inguinal ring to the superficial ring, above and parallel to the inguinal ligament", "Contains the femoral artery"], "answer": 2, "why": "Anterior wall = external oblique aponeurosis; posterior wall = transversalis fascia (+ conjoint tendon); floor = inguinal ligament.", "slides": [{"src": "files/slides/anat2-abdominal-wall/63.jpg", "lec": "Abdominal wall and inguinal canal", "n": 63}]}, {"q": "An indirect inguinal hernia:", "options": ["Leaves the abdomen through the deep inguinal ring, lateral to the inferior epigastric vessels", "Is always acquired in elderly men", "Passes below the inguinal ligament", "Passes through Hesselbach's triangle"], "answer": 0, "why": "Indirect = lateral to the inferior epigastric vessels through the deep ring; direct = medial, through Hesselbach's triangle.", "slides": [{"src": "files/slides/anat2-vessels/14.jpg", "lec": "Blood vessels of the abdomen", "n": 14}]}, {"q": "The linea alba is formed by:", "options": ["The tendinous intersections of rectus abdominis", "The transversalis fascia", "The fusion of the aponeuroses of the flat abdominal muscles in the midline", "The inguinal ligament"], "answer": 2, "why": "The aponeuroses of external oblique, internal oblique and transversus abdominis meet in the midline."}, {"q": "The lesser curvature of the stomach is supplied by:", "options": ["The right and left gastroepiploic arteries", "The superior mesenteric artery", "The right and left gastric arteries", "The short gastric arteries"], "answer": 2, "why": "Lesser curvature: left gastric (coeliac) + right gastric (common hepatic). Greater curvature: gastroepiploic arteries.", "slides": [{"src": "files/slides/anat2-stomach-oesophagus/62.jpg", "lec": "Oesophagus and stomach", "n": 62}]}, {"q": "The oesophagus crosses the diaphragm at the level of:", "options": ["T8", "T10", "L1", "T12"], "answer": 1, "why": "Oesophageal hiatus at T10, with the vagal trunks.", "slides": [{"src": "files/slides/anat2-stomach-oesophagus/09.jpg", "lec": "Oesophagus and stomach", "n": 9}]}, {"q": "The duodenojejunal flexure is held by:", "options": ["The falciform ligament", "The gastrosplenic ligament", "The suspensory ligament of the duodenum (ligament of Treitz)", "The round ligament"], "answer": 2, "why": "The ligament of Treitz marks the end of the duodenum and is the landmark between upper and lower GI bleeding.", "slides": [{"src": "files/slides/anat2-small-intestine/37.jpg", "lec": "The small intestine", "n": 37}]}, {"q": "Compared with the ileum, the jejunum has:", "options": ["More Peyer's patches", "More arterial arcades and shorter vasa recta", "A smaller diameter and fat-laden mesentery", "Thicker walls, more plicae circulares and longer vasa recta"], "answer": 3, "why": "Jejunum: wider, thicker, more circular folds, few arcades, long vasa recta. Ileum: Peyer's patches, many arcades.", "slides": [{"src": "files/slides/anat2-colon/08.jpg", "lec": "The colon and appendix", "n": 8}]}, {"q": "Features that distinguish the colon from the small intestine include:", "options": ["A complete outer longitudinal muscle layer", "Taeniae coli, haustra and epiploic appendages", "Plicae circulares", "Villi and Peyer's patches"], "answer": 1, "why": "The three taeniae coli, haustrations and appendices epiploicae identify the large bowel.", "slides": [{"src": "files/slides/anat2-colon/08.jpg", "lec": "The colon and appendix", "n": 8}]}, {"q": "The appendix is usually located by following:", "options": ["The falciform ligament", "The taeniae coli of the caecum to where they converge", "The ileocolic vein upward", "The sigmoid mesocolon"], "answer": 1, "why": "The taeniae converge on the base of the appendix (McBurney's point on the surface).", "slides": [{"src": "files/slides/anat2-colon/08.jpg", "lec": "The colon and appendix", "n": 8}]}, {"q": "The hepatic portal vein is formed by the union of:", "options": ["The splenic vein and the superior mesenteric vein behind the neck of the pancreas", "The left and right hepatic veins", "The inferior vena cava and the renal veins", "The inferior mesenteric vein and the left gastric vein only"], "answer": 0, "why": "SMV + splenic vein behind the pancreatic neck; the IMV usually drains into the splenic vein.", "slides": [{"src": "files/slides/anat2-pancreas/13.jpg", "lec": "The pancreas", "n": 13}]}, {"q": "The hepatoduodenal ligament (free edge of the lesser omentum) contains:", "options": ["The inferior vena cava", "The portal vein, the proper hepatic artery and the common bile duct", "The hepatic veins", "The splenic artery"], "answer": 1, "why": "The portal triad: bile duct (right, anterior), hepatic artery (left, anterior), portal vein (posterior)."}, {"q": "Calot's triangle (cystohepatic triangle) is bounded by:", "options": ["The common bile duct, the duodenum and the pancreas", "The portal vein, the IVC and the caudate lobe", "The left and right hepatic ducts and the gallbladder", "The cystic duct, the common hepatic duct and the inferior surface of the liver"], "answer": 3, "why": "It contains the cystic artery, which must be identified during cholecystectomy.", "slides": [{"src": "files/slides/anat2-biliary/28.jpg", "lec": "The biliary system", "n": 28}]}, {"q": "The common bile duct usually opens into:", "options": ["The second (descending) part of the duodenum at the major duodenal papilla", "The jejunum", "The third part of the duodenum", "The first part of the duodenum"], "answer": 0, "why": "With the main pancreatic duct, through the hepatopancreatic ampulla (of Vater) controlled by the sphincter of Oddi.", "slides": [{"src": "files/slides/anat2-pancreas/25.jpg", "lec": "The pancreas", "n": 25}]}, {"q": "The pancreas is:", "options": ["Mostly retroperitoneal, except the tail which reaches the splenic hilum", "Supplied only by the superior mesenteric artery", "Located in the right iliac fossa", "Entirely intraperitoneal"], "answer": 0, "why": "Head in the duodenal C-loop, tail in the splenorenal ligament; supplied by splenic and pancreaticoduodenal arteries.", "slides": [{"src": "files/slides/anat2-pancreas/18.jpg", "lec": "The pancreas", "n": 18}]}, {"q": "The spleen lies against ribs:", "options": ["11 and 12 on the right", "5 to 7 on the left", "9 to 11 on the left", "1 to 3 on the right"], "answer": 2, "why": "Spleen: '1, 3, 5, 7, 9, 11' — 1 × 3 × 5 inches, 7 oz, ribs 9 to 11 on the left.", "slides": [{"src": "files/slides/anat2-spleen/04.jpg", "lec": "The spleen", "n": 4}]}, {"q": "The coeliac trunk arises at the level of:", "options": ["T8", "T12", "L4", "L3"], "answer": 1, "why": "Coeliac T12, SMA L1, renal arteries L1-L2, IMA L3, bifurcation L4.", "slides": [{"src": "files/slides/anat2-vessels/06.jpg", "lec": "Blood vessels of the abdomen", "n": 6}]}, {"q": "The branches of the coeliac trunk are:", "options": ["Left gastric, splenic and common hepatic arteries", "Left colic, sigmoid and superior rectal arteries", "Superior mesenteric and inferior mesenteric arteries", "Right gastric, splenic and ileocolic arteries"], "answer": 0, "why": "Coeliac trunk = left gastric, splenic, common hepatic (foregut).", "slides": [{"src": "files/slides/anat2-stomach-oesophagus/62.jpg", "lec": "Oesophagus and stomach", "n": 62}]}, {"q": "Parasympathetic supply to the descending colon and rectum comes from:", "options": ["The greater splanchnic nerve", "The vagus nerve", "The pelvic splanchnic nerves (S2-S4)", "The phrenic nerve"], "answer": 2, "why": "The vagus reaches about two-thirds of the transverse colon; beyond that, pelvic splanchnic nerves (S2-S4).", "slides": [{"src": "files/slides/anat2-lymph-nerves/45.jpg", "lec": "Lymphatics and innervation of the", "n": 45}]}, {"q": "The internal iliac artery supplies mainly:", "options": ["The kidneys", "The pelvic organs, perineum and gluteal region", "The lower limb", "The anterior abdominal wall above the umbilicus"], "answer": 1, "why": "The external iliac continues as the femoral artery to the lower limb.", "slides": [{"src": "files/slides/anat2-pelvic-vessels/05.jpg", "lec": "Pelvic vessels, lymphatics and", "n": 5}]}, {"q": "The levator ani is composed of:", "options": ["Obturator internus and piriformis", "The external anal sphincter only", "Ischiocavernosus and bulbospongiosus", "Pubococcygeus, puborectalis and iliococcygeus"], "answer": 3, "why": "With coccygeus, the levator ani forms the pelvic diaphragm; puborectalis keeps the anorectal angle.", "slides": [{"src": "files/slides/anat2-perineum/31.jpg", "lec": "Perineum and pelvic floor", "n": 31}]}]}, {"id": "y1-physio1-sina-mock", "subject": "physio1", "title": "Sina mock exam: Physiology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering cardiovascular, respiratory, digestive and endocrine physiology. One answer per question, each with a short explanation.", "questions": [{"q": "The normal pacemaker of the heart is:", "options": ["The sinoatrial node", "The bundle of His", "The Purkinje fibres", "The atrioventricular node"], "answer": 0, "why": "The SA node has the fastest intrinsic rate (≈60-100/min) and sets the rhythm.", "slides": [{"src": "files/slides/physio1-ecg/05.jpg", "lec": "Electrocardiography (ECG)", "n": 5}]}, {"q": "The plateau phase (phase 2) of the ventricular action potential is mainly due to:", "options": ["Fast Na+ entry", "Cl- entry", "Slow Ca2+ entry through L-type channels balanced by K+ exit", "Na+/K+ ATPase activity"], "answer": 2, "why": "L-type Ca2+ influx balances K+ efflux, prolonging the action potential and the refractory period.", "slides": [{"src": "files/slides/physio1-ecg/09.jpg", "lec": "Electrocardiography (ECG)", "n": 9}]}, {"q": "Cardiac output equals:", "options": ["End-diastolic volume − heart rate", "Stroke volume / heart rate", "Mean arterial pressure × heart rate", "Heart rate × stroke volume"], "answer": 3, "why": "CO = HR × SV (≈ 70 × 70 mL ≈ 5 L/min).", "slides": [{"src": "files/slides/physio1-cardiac-cycle/26.jpg", "lec": "The cardiac cycle and cardiac output", "n": 26}]}, {"q": "According to the Frank-Starling law, stroke volume increases when:", "options": ["End-diastolic volume (preload) increases", "Ventricular filling decreases", "Heart rate increases above 180/min", "Afterload increases"], "answer": 0, "why": "Greater stretch of the myocardium leads to a stronger contraction, within physiological limits.", "slides": [{"src": "files/slides/physio1-cardiac-cycle/35.jpg", "lec": "The cardiac cycle and cardiac output", "n": 35}]}, {"q": "During isovolumetric contraction:", "options": ["The aortic valve is open", "Ventricular volume falls quickly", "The mitral valve is open", "All valves are closed and ventricular pressure rises"], "answer": 3, "why": "Between closure of the AV valves (S1) and opening of the semilunar valves."}, {"q": "On the ECG, the QRS complex represents:", "options": ["Ventricular repolarisation", "Atrial depolarisation", "Ventricular depolarisation", "Conduction through the AV node only"], "answer": 2, "why": "P = atrial depolarisation, QRS = ventricular depolarisation, T = ventricular repolarisation.", "slides": [{"src": "files/slides/physio1-ecg/31.jpg", "lec": "Electrocardiography (ECG)", "n": 31}]}, {"q": "A normal PR interval is:", "options": ["0.12-0.20 s", "More than 0.44 s", "0.04-0.08 s", "0.30-0.40 s"], "answer": 0, "why": "PR > 0.20 s = first-degree AV block.", "slides": [{"src": "files/slides/physio1-ecg/43.jpg", "lec": "Electrocardiography (ECG)", "n": 43}]}, {"q": "Vital capacity equals:", "options": ["Residual volume + tidal volume", "Functional residual capacity − tidal volume", "Tidal volume + inspiratory reserve volume + expiratory reserve volume", "Total lung capacity + residual volume"], "answer": 2, "why": "VC = TV + IRV + ERV; TLC = VC + RV.", "slides": [{"src": "files/slides/physio1-lung-volumes/21.jpg", "lec": "Lung volumes and capacities", "n": 21}]}, {"q": "Which volume cannot be measured by simple spirometry?", "options": ["Tidal volume", "Expiratory reserve volume", "Residual volume", "Inspiratory reserve volume"], "answer": 2, "why": "Residual volume (and so FRC and TLC) needs helium dilution, nitrogen washout or plethysmography.", "slides": [{"src": "files/slides/physio1-lung-volumes/19.jpg", "lec": "Lung volumes and capacities", "n": 19}]}, {"q": "Hypoxic pulmonary vasoconstriction:", "options": ["Happens in systemic arteries as well", "Increases ventilation-perfusion mismatch", "Dilates vessels in poorly ventilated areas", "Diverts blood away from poorly ventilated alveoli"], "answer": 3, "why": "Unlike systemic vessels, pulmonary vessels constrict in hypoxia, matching perfusion to ventilation.", "slides": [{"src": "files/slides/physio1-pulmonary-vascular/05.jpg", "lec": "Pulmonary vascular physiology", "n": 5}]}, {"q": "The pulmonary circulation is a:", "options": ["Low-flow system receiving 10% of the cardiac output", "High-pressure, high-resistance system", "System with a mean pressure of about 90 mmHg", "Low-pressure, low-resistance system"], "answer": 3, "why": "Mean pulmonary artery pressure ≈ 15 mmHg; it receives the whole right ventricular output."}, {"q": "The swallowing reflex centre is located in:", "options": ["The cerebellum", "The spinal cord at C5", "The medulla oblongata (brainstem)", "The cerebral cortex"], "answer": 2, "why": "The oral phase is voluntary; the pharyngeal and oesophageal phases are reflex, controlled by the medulla.", "slides": [{"src": "files/slides/physio1-oral/27.jpg", "lec": "Saliva, mastication and deglutition", "n": 27}]}, {"q": "Hydrochloric acid in the stomach is secreted by:", "options": ["G cells", "Parietal cells", "Chief cells", "Mucous neck cells"], "answer": 1, "why": "Parietal (oxyntic) cells secrete HCl and intrinsic factor; chief cells secrete pepsinogen; G cells secrete gastrin.", "slides": [{"src": "files/slides/physio1-gastric-secretion/33.jpg", "lec": "Gastric secretion", "n": 33}]}, {"q": "Which substance does NOT stimulate acid secretion by parietal cells?", "options": ["Histamine", "Acetylcholine", "Gastrin", "Somatostatin"], "answer": 3, "why": "Somatostatin inhibits acid secretion; ACh, gastrin and histamine stimulate it.", "slides": [{"src": "files/slides/physio1-gastric-secretion/44.jpg", "lec": "Gastric secretion", "n": 44}]}, {"q": "Secretin mainly stimulates:", "options": ["Pancreatic enzyme secretion", "Gallbladder contraction", "Gastric acid secretion", "Pancreatic bicarbonate secretion"], "answer": 3, "why": "Secretin (from S cells, released by acid in the duodenum) causes bicarbonate-rich pancreatic juice; CCK drives enzymes and gallbladder contraction.", "slides": [{"src": "files/slides/physio1-pancreas/04.jpg", "lec": "Exocrine pancreas", "n": 4}]}, {"q": "The migrating motor complex (MMC):", "options": ["Is triggered by gastrin only", "Happens during fasting and sweeps residue through the small bowel", "Is a colonic movement", "Happens mainly after meals"], "answer": 1, "why": "MMCs are fasting 'housekeeper' waves, linked to motilin.", "slides": [{"src": "files/slides/physio1-small-intestine-motility/06.jpg", "lec": "Small intestine motility", "n": 6}]}, {"q": "Most water absorption in the gut happens in:", "options": ["The rectum", "The stomach", "The small intestine", "The colon"], "answer": 2, "why": "About 80% of water is absorbed in the small intestine; the colon absorbs most of the rest.", "slides": [{"src": "files/slides/physio1-small-intestine-motility/10.jpg", "lec": "Small intestine motility", "n": 10}]}, {"q": "Glucose is absorbed across the apical membrane of the enterocyte by:", "options": ["Endocytosis", "GLUT5", "Simple diffusion", "SGLT1, coupled to Na+"], "answer": 3, "why": "SGLT1 (Na+-glucose cotransport) apically; GLUT2 basolaterally. Fructose uses GLUT5.", "slides": [{"src": "files/slides/physio1-absorption/16.jpg", "lec": "Intestinal absorption", "n": 16}]}, {"q": "Hormones secreted by the anterior pituitary include:", "options": ["Cortisol and aldosterone", "T3 and T4", "ADH and oxytocin", "TSH, ACTH, GH, prolactin, FSH and LH"], "answer": 3, "why": "ADH and oxytocin are made in the hypothalamus and released from the posterior pituitary.", "slides": [{"src": "files/slides/physio1-hypothalamus-pituitary/05.jpg", "lec": "Hypothalamus and pituitary", "n": 5}]}, {"q": "Most circulating thyroid hormone is:", "options": ["Free T4", "Free T3", "T4 bound to plasma proteins (mainly TBG)", "Reverse T3"], "answer": 2, "why": "Over 99% is protein-bound; T4 is the main secreted form and is converted to the active T3 in tissues.", "slides": [{"src": "files/slides/physio1-thyroid/03.jpg", "lec": "Thyroid physiology", "n": 3}]}]}, {"id": "y1-biochem1-sina-mock", "subject": "biochem1", "title": "Sina mock exam: Biochemistry", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering biomolecules, enzymes and metabolism. One answer per question, each with a short explanation.", "questions": [{"q": "Which amino acid has no chiral (asymmetric) carbon?", "options": ["Leucine", "Serine", "Glycine", "Alanine"], "answer": 2, "why": "Glycine's side chain is H, so its α-carbon carries two identical groups.", "slides": [{"src": "files/slides/biochem1-amino-acids/19.jpg", "lec": "Introduction to biochemistry and", "n": 19}]}, {"q": "Amino acids found in human proteins are of the:", "options": ["β series", "Racemic mixture", "D series", "L series"], "answer": 3, "why": "Proteins are made of L-α-amino acids."}, {"q": "At its isoelectric point (pI), an amino acid:", "options": ["Carries a net negative charge", "Is fully protonated", "Carries no net charge", "Carries a net positive charge"], "answer": 2, "why": "At the pI the zwitterion has zero net charge and does not move in an electric field.", "slides": [{"src": "files/slides/biochem1-amino-acids/21.jpg", "lec": "Introduction to biochemistry and", "n": 21}]}, {"q": "The peptide bond:", "options": ["Rotates freely", "Is planar, with partial double-bond character", "Is a hydrogen bond", "Links two side chains"], "answer": 1, "why": "Resonance gives the C-N bond partial double-bond character, so it is rigid and usually trans.", "slides": [{"src": "files/slides/biochem1-proteins/06.jpg", "lec": "Peptides and proteins", "n": 6}]}, {"q": "The α-helix and β-pleated sheet are examples of:", "options": ["Secondary structure stabilised by hydrogen bonds between backbone groups", "Disulfide bonds", "Quaternary structure", "Primary structure"], "answer": 0, "why": "Secondary structure = local folding held by H-bonds between C=O and N-H of the backbone.", "slides": [{"src": "files/slides/biochem1-proteins/13.jpg", "lec": "Peptides and proteins", "n": 13}]}, {"q": "The Michaelis constant (Km) is:", "options": ["The substrate concentration that gives half of Vmax", "Raised by a non-competitive inhibitor", "The maximum rate of the reaction", "Independent of the substrate"], "answer": 0, "why": "Low Km = high affinity. Competitive inhibitors raise apparent Km; non-competitive inhibitors lower Vmax."}, {"q": "A competitive inhibitor:", "options": ["Raises the apparent Km and leaves Vmax unchanged", "Cannot be overcome by excess substrate", "Lowers Vmax and leaves Km unchanged", "Binds only the enzyme-substrate complex"], "answer": 0, "why": "It competes for the active site; enough substrate restores Vmax.", "slides": [{"src": "files/slides/biochem1-enzymes/15.jpg", "lec": "Enzymes and coenzymes", "n": 15}]}, {"q": "Glucose and galactose are:", "options": ["Anomers", "Ketoses", "Epimers at carbon 4", "Enantiomers"], "answer": 2, "why": "They differ only in the configuration at C-4.", "slides": [{"src": "files/slides/biochem1-carbohydrates/21.jpg", "lec": "Carbohydrates: structure and", "n": 21}]}, {"q": "Sucrose is made of:", "options": ["Galactose + fructose", "Glucose + fructose", "Glucose + galactose", "Glucose + glucose"], "answer": 1, "why": "Lactose = glucose + galactose; maltose = glucose + glucose.", "slides": [{"src": "files/slides/biochem1-carb-metabolism/06.jpg", "lec": "Carbohydrate metabolism", "n": 6}]}, {"q": "Glycogen differs from amylose because it:", "options": ["Has only α(1→4) bonds", "Contains β(1→4) bonds", "Is more highly branched with α(1→6) bonds", "Is a plant polysaccharide"], "answer": 2, "why": "Glycogen branches every 8-12 residues, more often than amylopectin.", "slides": [{"src": "files/slides/biochem1-carbohydrates/40.jpg", "lec": "Carbohydrates: structure and", "n": 40}]}, {"q": "Essential fatty acids for humans include:", "options": ["Stearic acid", "Palmitic acid", "Linoleic and α-linolenic acids", "Oleic acid"], "answer": 2, "why": "Humans cannot insert double bonds beyond C-9, so ω-6 linoleic and ω-3 α-linolenic acids must come from the diet.", "slides": [{"src": "files/slides/biochem1-lipids/22.jpg", "lec": "Lipids: structure, classes and", "n": 22}]}, {"q": "Which lipoprotein carries most cholesterol to peripheral tissues?", "options": ["Chylomicrons", "HDL", "LDL", "VLDL"], "answer": 2, "why": "LDL delivers cholesterol to tissues; HDL brings it back to the liver (reverse transport).", "slides": [{"src": "files/slides/biochem1-lipids/47.jpg", "lec": "Lipids: structure, classes and", "n": 47}]}, {"q": "In DNA, adenine pairs with:", "options": ["Guanine by three hydrogen bonds", "Thymine by two hydrogen bonds", "Cytosine by two hydrogen bonds", "Uracil"], "answer": 1, "why": "A=T (2 H-bonds), G≡C (3 H-bonds). In RNA, uracil replaces thymine.", "slides": [{"src": "files/slides/biochem1-nucleotides/07.jpg", "lec": "Nucleotides and nucleic acids", "n": 7}]}, {"q": "The rate-limiting enzyme of glycolysis is:", "options": ["Aldolase", "Hexokinase", "Phosphofructokinase-1", "Pyruvate kinase"], "answer": 2, "why": "PFK-1 is activated by AMP and fructose-2,6-bisphosphate and inhibited by ATP and citrate."}, {"q": "Under anaerobic conditions, pyruvate in muscle is converted to:", "options": ["Acetyl-CoA", "Lactate, which regenerates NAD+", "Ethanol", "Oxaloacetate"], "answer": 1, "why": "Lactate dehydrogenase regenerates NAD+ so glycolysis can continue.", "slides": [{"src": "files/slides/biochem1-carb-metabolism/21.jpg", "lec": "Carbohydrate metabolism", "n": 21}]}, {"q": "Gluconeogenesis mainly happens in:", "options": ["The liver (and the renal cortex)", "The brain", "Skeletal muscle", "Red blood cells"], "answer": 0, "why": "Muscle lacks glucose-6-phosphatase and cannot release free glucose."}, {"q": "β-oxidation of fatty acids takes place in:", "options": ["The mitochondrial matrix", "The nucleus", "The cytosol", "The endoplasmic reticulum"], "answer": 0, "why": "Long-chain fatty acids enter via the carnitine shuttle; synthesis happens in the cytosol.", "slides": [{"src": "files/slides/biochem1-lipid-metabolism/12.jpg", "lec": "Lipid metabolism", "n": 12}]}, {"q": "The rate-limiting enzyme of cholesterol synthesis is:", "options": ["Acetyl-CoA carboxylase", "Carnitine palmitoyltransferase I", "HMG-CoA reductase", "Lipoprotein lipase"], "answer": 2, "why": "It is the target of statins.", "slides": [{"src": "files/slides/biochem1-lipid-metabolism/33.jpg", "lec": "Lipid metabolism", "n": 33}]}, {"q": "The urea cycle takes place in:", "options": ["The kidney only", "Muscle", "The liver, partly in mitochondria and partly in the cytosol", "The brain"], "answer": 2, "why": "Carbamoyl phosphate and citrulline form in mitochondria; the rest of the cycle is cytosolic.", "slides": [{"src": "files/slides/biochem1-aa-metabolism/16.jpg", "lec": "Amino acid metabolism and the urea cycle", "n": 16}]}, {"q": "Transamination reactions require the coenzyme:", "options": ["Coenzyme A", "Thiamine pyrophosphate", "Biotin", "Pyridoxal phosphate (vitamin B6)"], "answer": 3, "why": "ALT and AST use pyridoxal phosphate.", "slides": [{"src": "files/slides/biochem1-enzymes/23.jpg", "lec": "Enzymes and coenzymes", "n": 23}]}]}, {"id": "y1-immuno1-sina-mock", "subject": "immuno1", "title": "Sina mock exam: Immunology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering lymphoid organs, antibodies, complement, innate immunity, MHC and lab tests. One answer per question, each with a short explanation.", "questions": [{"q": "Primary (central) lymphoid organs are:", "options": ["Tonsils and Peyer's patches", "Bone marrow and thymus", "Spleen and lymph nodes", "Liver and spleen"], "answer": 1, "why": "Lymphocytes are made and selected in the bone marrow (B) and thymus (T); they meet antigen in secondary organs.", "slides": [{"src": "files/slides/immuno1-lymphoid/12.jpg", "lec": "Lymphoid organs and lymphocyte selection", "n": 12}]}, {"q": "Positive selection of T cells in the thymus keeps cells that:", "options": ["Express both CD4 and CD8 at the end", "Do not bind MHC at all", "Bind self-MHC with moderate affinity", "Bind self-antigens strongly"], "answer": 2, "why": "Positive selection (cortex) = MHC restriction; negative selection (medulla) removes strongly self-reactive cells.", "slides": [{"src": "files/slides/immuno1-cells/28.jpg", "lec": "Hematopoiesis and cells of the immune", "n": 28}]}, {"q": "Which cell is the main antigen-presenting cell for naive T cells?", "options": ["Erythrocyte", "Neutrophil", "Dendritic cell", "Eosinophil"], "answer": 2, "why": "Dendritic cells are the most effective activators of naive T cells.", "slides": [{"src": "files/slides/immuno1-lymphoid/33.jpg", "lec": "Lymphoid organs and lymphocyte selection", "n": 33}]}, {"q": "An epitope is:", "options": ["The part of an antigen recognised by an antibody or T-cell receptor", "The whole antigen molecule", "A carrier protein", "The constant region of an antibody"], "answer": 0, "why": "Also called the antigenic determinant; a hapten needs a carrier to be immunogenic.", "slides": [{"src": "files/slides/immuno1-antigens/12.jpg", "lec": "Antigens", "n": 12}]}, {"q": "The immunoglobulin that crosses the placenta is:", "options": ["IgG", "IgE", "IgA", "IgM"], "answer": 0, "why": "IgG is carried across by the neonatal Fc receptor (FcRn).", "slides": [{"src": "files/slides/immuno1-immunoglobulins/25.jpg", "lec": "Immunoglobulins and antibody functions", "n": 25}]}, {"q": "The first antibody produced in a primary immune response is:", "options": ["IgG", "IgM", "IgD", "IgE"], "answer": 1, "why": "IgM (pentamer) dominates the primary response; IgG dominates the secondary response.", "slides": [{"src": "files/slides/immuno1-immunoglobulins/17.jpg", "lec": "Immunoglobulins and antibody functions", "n": 17}]}, {"q": "Secretory IgA is:", "options": ["A pentamer", "The main antibody in allergy", "A dimer with a J chain and secretory component", "Found mostly in serum"], "answer": 2, "why": "It protects mucosal surfaces and is present in breast milk.", "slides": [{"src": "files/slides/immuno1-immunoglobulins/28.jpg", "lec": "Immunoglobulins and antibody functions", "n": 28}]}, {"q": "The classical complement pathway is started by:", "options": ["Factor B", "Spontaneous hydrolysis of C3", "C1q binding to antigen-antibody complexes", "Mannose-binding lectin"], "answer": 2, "why": "Classical = antibody (IgM, IgG); lectin = MBL; alternative = spontaneous C3 activation on surfaces.", "slides": [{"src": "files/slides/immuno1-complement/16.jpg", "lec": "The complement system", "n": 16}]}, {"q": "The membrane attack complex is formed by:", "options": ["C4b2a", "C1q, C1r, C1s", "C5b-C9", "C3a and C5a"], "answer": 2, "why": "C5b, C6, C7, C8 and multiple C9 form a pore.", "slides": [{"src": "files/slides/immuno1-complement/15.jpg", "lec": "The complement system", "n": 15}]}, {"q": "Which complement fragment is the main opsonin?", "options": ["C9", "C3b", "C2a", "C5a"], "answer": 1, "why": "C3b coats microbes for phagocytosis; C3a and C5a are anaphylatoxins and chemoattractants."}, {"q": "Pattern recognition receptors such as Toll-like receptors recognise:", "options": ["Only self-antigens", "Antibodies", "Conserved microbial molecules (PAMPs)", "Specific peptide-MHC complexes"], "answer": 2, "why": "They belong to innate immunity, e.g. TLR4 recognises LPS.", "slides": [{"src": "files/slides/immuno1-innate/32.jpg", "lec": "Innate immunity", "n": 32}]}, {"q": "The first leukocytes to arrive at a site of acute inflammation are usually:", "options": ["Lymphocytes", "Plasma cells", "Neutrophils", "Eosinophils"], "answer": 2, "why": "Neutrophils dominate in the first 6-24 hours, then monocytes and macrophages."}, {"q": "The correct order of leukocyte extravasation is:", "options": ["Adhesion, rolling, transmigration", "Chemotaxis, rolling, phagocytosis", "Transmigration, rolling, adhesion", "Rolling (selectins), firm adhesion (integrins), transmigration, chemotaxis"], "answer": 3, "why": "Selectins drive rolling, integrins (LFA-1 binding ICAM-1) drive firm adhesion, then diapedesis via PECAM-1.", "slides": [{"src": "files/slides/immuno1-inflammation/17.jpg", "lec": "The inflammatory response", "n": 17}]}, {"q": "The respiratory (oxidative) burst of phagocytes depends on:", "options": ["Perforin", "NADPH oxidase", "Complement C9", "Lysozyme"], "answer": 1, "why": "Its absence causes chronic granulomatous disease.", "slides": [{"src": "files/slides/immuno1-phagocytosis/22.jpg", "lec": "Phagocytosis and microbicidal processes", "n": 22}]}, {"q": "MHC class I molecules:", "options": ["Present extracellular peptides to CD4+ T cells", "Are found only on antigen-presenting cells", "Are absent from all human cells", "Are found on all nucleated cells and present peptides to CD8+ T cells"], "answer": 3, "why": "Class I presents cytosolic (endogenous) peptides to CD8+; class II (APCs) presents exogenous peptides to CD4+.", "slides": [{"src": "files/slides/immuno1-mhc/07.jpg", "lec": "MHC and antigen-presenting cells", "n": 7}]}, {"q": "Natural killer (NK) cells kill cells that:", "options": ["Carry antibody on their surface only", "Have lost or reduced MHC class I ('missing self')", "Express high levels of MHC class I", "Are B lymphocytes"], "answer": 1, "why": "Loss of MHC I removes the inhibitory signal; NK cells also kill antibody-coated cells by ADCC.", "slides": [{"src": "files/slides/immuno1-innate/23.jpg", "lec": "Innate immunity", "n": 23}]}, {"q": "Immunological memory is a feature of:", "options": ["Neutrophils", "Complement only", "Innate immunity", "Adaptive immunity"], "answer": 3, "why": "Memory B and T cells give faster, stronger secondary responses; this is the basis of vaccination.", "slides": [{"src": "files/slides/immuno1-innate/05.jpg", "lec": "Innate immunity", "n": 5}]}, {"q": "Th1 cells mainly produce:", "options": ["IL-4 and IL-5", "IFN-γ, which activates macrophages", "IL-17 only", "IgE"], "answer": 1, "why": "Th1: IFN-γ (intracellular microbes); Th2: IL-4, IL-5, IL-13 (helminths, allergy); Th17: IL-17 (extracellular bacteria, fungi).", "slides": [{"src": "files/slides/immuno1-dynamics/34.jpg", "lec": "Dynamics of the immune response", "n": 34}]}, {"q": "In an ELISA, the signal is produced by:", "options": ["Agglutination of red cells", "Complement lysis", "An enzyme linked to an antibody acting on a substrate", "A radioactive label"], "answer": 2, "why": "Enzyme-linked immunosorbent assay: the enzyme turns a substrate into a coloured product.", "slides": [{"src": "files/slides/immuno1-testing/21.jpg", "lec": "Immunological testing: diagnostic", "n": 21}]}, {"q": "A direct Coombs test detects:", "options": ["Free antibodies in the patient's serum", "Antibodies or complement already bound to the patient's red cells", "Antinuclear antibodies", "ABO blood group only"], "answer": 1, "why": "The indirect Coombs test detects free antibodies in serum (e.g. antenatal screening, cross-matching)."}]}, {"id": "y1-hemato1-sina-mock", "subject": "hemato1", "title": "Sina mock exam: Hematology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering red cells, iron and vitamins, white cells, haemostasis and transfusion. One answer per question, each with a short explanation.", "questions": [{"q": "In adults, haematopoiesis normally takes place in:", "options": ["The yolk sac", "The red bone marrow of the axial skeleton and proximal long bones", "The lymph nodes", "The liver and spleen"], "answer": 1, "why": "Yolk sac → liver/spleen → bone marrow; in adults it is restricted to flat bones, vertebrae and proximal femur and humerus.", "slides": [{"src": "files/slides/hemato1-wbc-1/48.jpg", "lec": "White blood cells, part I: granulocytes", "n": 48}]}, {"q": "The main hormone that drives erythropoiesis is:", "options": ["Interleukin-5", "Thrombopoietin", "G-CSF", "Erythropoietin, produced mainly by the kidney"], "answer": 3, "why": "Peritubular cells of the kidney release EPO in response to hypoxia.", "slides": [{"src": "files/slides/hemato1-rbc/59.jpg", "lec": "Red blood cells and erythropoiesis", "n": 59}]}, {"q": "The normal life span of a red blood cell is about:", "options": ["120 days", "30 days", "1 year", "10 days"], "answer": 0, "why": "Old red cells are removed by macrophages, mainly in the spleen.", "slides": [{"src": "files/slides/hemato1-rbc/02.jpg", "lec": "Red blood cells and erythropoiesis", "n": 2}]}, {"q": "Dietary iron is absorbed mainly in:", "options": ["The colon", "The stomach", "The duodenum and upper jejunum", "The terminal ileum"], "answer": 2, "why": "Absorption is regulated by hepcidin, which blocks ferroportin. Vitamin B12 is absorbed in the terminal ileum.", "slides": [{"src": "files/slides/hemato1-iron/11.jpg", "lec": "Iron metabolism", "n": 11}]}, {"q": "The best single test to confirm iron deficiency is:", "options": ["Serum iron", "MCHC", "Reticulocyte count", "Serum ferritin (low)"], "answer": 3, "why": "Low ferritin reflects depleted stores; ferritin rises with inflammation, so it can be falsely normal.", "slides": [{"src": "files/slides/hemato1-iron/42.jpg", "lec": "Iron metabolism", "n": 42}]}, {"q": "Vitamin B12 absorption requires:", "options": ["Transferrin", "Intrinsic factor from gastric parietal cells, with absorption in the terminal ileum", "Hydrochloric acid only", "Bile salts"], "answer": 1, "why": "Pernicious anaemia: autoantibodies against parietal cells or intrinsic factor.", "slides": [{"src": "files/slides/hemato1-anaemias/46.jpg", "lec": "Anaemias", "n": 46}]}, {"q": "Folate or vitamin B12 deficiency causes:", "options": ["Haemolytic anaemia with spherocytes", "Microcytic hypochromic anaemia", "Polycythaemia", "Megaloblastic macrocytic anaemia with hypersegmented neutrophils"], "answer": 3, "why": "Impaired DNA synthesis delays nuclear maturation.", "slides": [{"src": "files/slides/hemato1-anaemias/51.jpg", "lec": "Anaemias", "n": 51}]}, {"q": "Mean corpuscular volume (MCV) is:", "options": ["White cell count × platelets", "Haemoglobin / haematocrit", "Haemoglobin / red cell count", "Haematocrit / red cell count"], "answer": 3, "why": "MCV = Hct / RBC (normal ≈ 80-100 fL); MCH = Hb / RBC; MCHC = Hb / Hct."}, {"q": "A microcytic anaemia (low MCV) is typical of:", "options": ["Hypothyroidism", "Alcohol excess", "Iron deficiency and thalassaemia", "Vitamin B12 deficiency"], "answer": 2, "why": "Microcytic: iron deficiency, thalassaemia, anaemia of chronic disease (sometimes), sideroblastic anaemia.", "slides": [{"src": "files/slides/hemato1-anaemias/16.jpg", "lec": "Anaemias", "n": 16}]}, {"q": "A high reticulocyte count in an anaemic patient suggests:", "options": ["Iron deficiency before treatment", "Haemolysis or acute blood loss (regenerative anaemia)", "Bone marrow failure", "Aplastic anaemia"], "answer": 1, "why": "The marrow responds normally by releasing young red cells.", "slides": [{"src": "files/slides/hemato1-anaemias/16.jpg", "lec": "Anaemias", "n": 16}]}, {"q": "The most abundant white blood cell in adult blood is:", "options": ["Monocyte", "Lymphocyte", "Neutrophil", "Eosinophil"], "answer": 2, "why": "Neutrophils ≈ 50-70%, lymphocytes ≈ 20-40%."}, {"q": "Eosinophilia is classically seen in:", "options": ["Parasitic (helminth) infections and allergy", "Bacterial pneumonia", "Iron deficiency", "Viral hepatitis"], "answer": 0, "why": "Eosinophils fight helminths and take part in allergic reactions.", "slides": [{"src": "files/slides/hemato1-wbc-1/67.jpg", "lec": "White blood cells, part I: granulocytes", "n": 67}]}, {"q": "Primary haemostasis involves:", "options": ["Fibrinolysis", "Formation of a fibrin clot", "Activation of factor X only", "Vasoconstriction and formation of the platelet plug"], "answer": 3, "why": "Platelets adhere (vWF binding GPIb), become activated and aggregate (fibrinogen bridging GPIIb/IIIa).", "slides": [{"src": "files/slides/hemato1-primary/59.jpg", "lec": "Primary haemostasis", "n": 59}]}, {"q": "Von Willebrand factor:", "options": ["Breaks down fibrin", "Is made by red cells", "Links platelets to exposed collagen and carries factor VIII", "Is a vitamin K-dependent factor"], "answer": 2, "why": "It is made by endothelial cells and megakaryocytes.", "slides": [{"src": "files/slides/hemato1-primary/42.jpg", "lec": "Primary haemostasis", "n": 42}]}, {"q": "The vitamin K-dependent coagulation factors are:", "options": ["I, V, VIII, XIII", "III and IV", "XI, XII only", "II, VII, IX, X (and proteins C and S)"], "answer": 3, "why": "Warfarin blocks their γ-carboxylation.", "slides": [{"src": "files/slides/hemato1-coagulation/15.jpg", "lec": "Coagulation (secondary haemostasis)", "n": 15}]}, {"q": "The prothrombin time (PT/INR) mainly explores:", "options": ["The extrinsic and common pathways (VII, X, V, II, fibrinogen)", "The intrinsic pathway (VIII, IX, XI, XII)", "Fibrinolysis only", "Platelet function"], "answer": 0, "why": "aPTT explores the intrinsic + common pathways and is prolonged in haemophilia A and B.", "slides": [{"src": "files/slides/hemato1-coagulation/51.jpg", "lec": "Coagulation (secondary haemostasis)", "n": 51}]}, {"q": "Haemophilia A is due to a deficiency of:", "options": ["Factor VIII", "Factor IX", "Factor VII", "Von Willebrand factor"], "answer": 0, "why": "X-linked recessive; haemophilia B = factor IX.", "slides": [{"src": "files/slides/hemato1-coagulation/59.jpg", "lec": "Coagulation (secondary haemostasis)", "n": 59}]}, {"q": "Thrombocytopenia is defined as a platelet count below:", "options": ["400 × 10⁹/L", "50 × 10⁹/L only", "1000 × 10⁹/L", "150 × 10⁹/L"], "answer": 3, "why": "Normal range ≈ 150-400 × 10⁹/L; spontaneous bleeding usually appears well below 20-30 × 10⁹/L.", "slides": [{"src": "files/slides/hemato1-cbc/48.jpg", "lec": "The complete blood count", "n": 48}]}, {"q": "A person with blood group O:", "options": ["Has A and B antigens on red cells", "Has no antibodies", "Has anti-A and anti-B antibodies in plasma", "Is the universal recipient"], "answer": 2, "why": "Group O red cells are the universal donor cells; AB is the universal plasma donor and red-cell recipient.", "slides": [{"src": "files/slides/hemato1-transfusion/09.jpg", "lec": "Blood groups and transfusion", "n": 9}]}, {"q": "Splenomegaly can cause:", "options": ["Raised platelet count in all cases", "Iron overload", "Hypersplenism with cytopenias (pooling and destruction of blood cells)", "Polycythaemia"], "answer": 2, "why": "An enlarged spleen sequesters platelets and red cells.", "slides": [{"src": "files/slides/hemato1-platelets/08.jpg", "lec": "Thrombocytopenia and thrombocytosis", "n": 8}]}]}, {"id": "y1-embryo1-sina-mock", "subject": "embryo1", "title": "Sina mock exam: Embryology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering gametogenesis to the fetal period and the digestive system. One answer per question, each with a short explanation.", "questions": [{"q": "Meiosis I in the human oocyte is arrested at:", "options": ["Telophase II", "Metaphase II until puberty", "Anaphase I", "Prophase I (diplotene) until shortly before ovulation"], "answer": 3, "why": "Primary oocytes stay in prophase I from fetal life; the secondary oocyte then arrests in metaphase II until fertilisation.", "slides": [{"src": "files/slides/embryo1-gametogenesis/24.jpg", "lec": "Gametogenesis", "n": 24}]}, {"q": "Spermatogenesis produces from one primary spermatocyte:", "options": ["Eight spermatids", "Two spermatids and two polar bodies", "One spermatozoon", "Four spermatids"], "answer": 3, "why": "Oogenesis gives one ovum and polar bodies.", "slides": [{"src": "files/slides/embryo1-gametogenesis/19.jpg", "lec": "Gametogenesis", "n": 19}]}, {"q": "Fertilisation usually takes place in:", "options": ["The ovary", "The ampulla of the uterine tube", "The uterine cavity", "The cervix"], "answer": 1, "why": "Implantation normally occurs in the posterior wall of the uterine body.", "slides": [{"src": "files/slides/embryo1-gametogenesis/21.jpg", "lec": "Gametogenesis", "n": 21}]}, {"q": "The cortical (zona) reaction:", "options": ["Allows several sperm to enter", "Triggers the acrosome reaction", "Starts capacitation", "Prevents polyspermy"], "answer": 3, "why": "Cortical granule enzymes modify the zona pellucida.", "slides": [{"src": "files/slides/embryo1-gametogenesis/45.jpg", "lec": "Gametogenesis", "n": 45}]}, {"q": "Implantation usually begins around:", "options": ["Day 21", "Day 14", "Day 6-7 after fertilisation", "Day 1 after fertilisation"], "answer": 2, "why": "The blastocyst hatches from the zona and attaches to the endometrium.", "slides": [{"src": "files/slides/embryo1-implantation/17.jpg", "lec": "Fertilisation to implantation", "n": 17}]}, {"q": "The syncytiotrophoblast secretes:", "options": ["hCG (human chorionic gonadotropin)", "Prolactin", "Oxytocin", "FSH"], "answer": 0, "why": "hCG maintains the corpus luteum and is the basis of pregnancy tests.", "slides": [{"src": "files/slides/embryo1-placenta/13.jpg", "lec": "The placenta", "n": 13}]}, {"q": "Gastrulation (week 3) forms:", "options": ["The placenta", "The bilaminar disc", "The neural tube only", "The three germ layers via the primitive streak"], "answer": 3, "why": "Epiblast cells migrate through the primitive streak to form endoderm and mesoderm; the remaining epiblast becomes ectoderm.", "slides": [{"src": "files/slides/embryo1-gastrulation/15.jpg", "lec": "Gastrulation and neurulation", "n": 15}]}, {"q": "The notochord induces:", "options": ["The liver", "The neural plate from the overlying ectoderm", "The somites to become blood", "The heart"], "answer": 1, "why": "Neurulation follows: neural folds form the neural tube.", "slides": [{"src": "files/slides/embryo1-gastrulation/33.jpg", "lec": "Gastrulation and neurulation", "n": 33}]}, {"q": "Which derives from the neural crest?", "options": ["Melanocytes and dorsal root ganglia", "The liver", "Skeletal muscle", "The spinal cord"], "answer": 0, "why": "Neural crest also forms the adrenal medulla, Schwann cells, and much of the facial skeleton.", "slides": [{"src": "files/slides/embryo1-gastrulation/32.jpg", "lec": "Gastrulation and neurulation", "n": 32}]}, {"q": "Failure of the posterior neuropore to close leads to:", "options": ["Cleft lip", "Anencephaly", "Spina bifida", "Hydrocele"], "answer": 2, "why": "Anterior neuropore failure gives anencephaly. Folic acid lowers the risk.", "slides": [{"src": "files/slides/embryo1-gastrulation/31.jpg", "lec": "Gastrulation and neurulation", "n": 31}]}, {"q": "Somites give rise to:", "options": ["The heart", "The gut epithelium", "Sclerotome, myotome and dermatome", "The kidneys"], "answer": 2, "why": "Vertebrae and ribs, skeletal muscle, dermis of the back.", "slides": [{"src": "files/slides/embryo1-folding/12.jpg", "lec": "Folding, somites and organogenesis", "n": 12}]}, {"q": "The epithelium of the gut tube derives from:", "options": ["Neural crest", "Endoderm", "Mesoderm", "Ectoderm"], "answer": 1, "why": "The muscle and connective tissue of the gut wall come from splanchnic mesoderm.", "slides": [{"src": "files/slides/embryo1-git/04.jpg", "lec": "Development of the digestive system", "n": 4}]}, {"q": "The embryonic period (organogenesis) lasts:", "options": ["The whole pregnancy", "Weeks 9-38", "Weeks 1-2", "Weeks 3-8"], "answer": 3, "why": "This is the most sensitive period for major malformations; from week 9 the fetal period is mainly growth.", "slides": [{"src": "files/slides/embryo1-fetal-period/08.jpg", "lec": "The fetal period", "n": 8}]}, {"q": "The fetal component of the placenta is:", "options": ["The myometrium", "The decidua parietalis", "The chorion frondosum", "The decidua basalis"], "answer": 2, "why": "Maternal component = decidua basalis.", "slides": [{"src": "files/slides/embryo1-placenta/09.jpg", "lec": "The placenta", "n": 9}]}, {"q": "The amniotic fluid:", "options": ["Is never swallowed by the fetus", "Has no protective role", "Is produced only by the placenta", "Allows fetal movement and lung development; it is swallowed and replaced by fetal urine"], "answer": 3, "why": "Oligohydramnios can result from renal agenesis; polyhydramnios from oesophageal atresia.", "slides": [{"src": "files/slides/embryo1-membranes/05.jpg", "lec": "Fetal membranes and fetal assessment", "n": 5}]}, {"q": "Oligohydramnios can be caused by:", "options": ["Anencephaly", "Oesophageal atresia", "Maternal diabetes", "Bilateral renal agenesis"], "answer": 3, "why": "Fetal urine is the main source of amniotic fluid in later pregnancy.", "slides": [{"src": "files/slides/embryo1-membranes/06.jpg", "lec": "Fetal membranes and fetal assessment", "n": 6}]}, {"q": "Physiological umbilical herniation of the midgut:", "options": ["Happens around week 6 and returns by week 10", "Involves the liver only", "Never happens in normal development", "Persists until birth"], "answer": 0, "why": "The midgut rotates 270° anticlockwise around the superior mesenteric artery. Failure of return = omphalocele.", "slides": [{"src": "files/slides/embryo1-git/35.jpg", "lec": "Development of the digestive system", "n": 35}]}, {"q": "The liver bud arises from:", "options": ["The neural crest", "The yolk sac mesoderm only", "The foregut endoderm (distal part)", "The hindgut"], "answer": 2, "why": "The hepatic diverticulum grows into the septum transversum.", "slides": [{"src": "files/slides/embryo1-git/17.jpg", "lec": "Development of the digestive system", "n": 17}]}, {"q": "The ventral and dorsal pancreatic buds fuse after:", "options": ["Rotation of the ventral bud behind the duodenum", "Closure of the neural tube", "Separation of the oesophagus", "Return of the midgut"], "answer": 0, "why": "The ventral bud forms the uncinate process and part of the head; abnormal rotation can cause annular pancreas.", "slides": [{"src": "files/slides/embryo1-git/21.jpg", "lec": "Development of the digestive system", "n": 21}]}, {"q": "Monozygotic twins sharing one chorion and one amnion usually come from splitting at:", "options": ["The 2-cell stage", "The morula stage", "After the formation of the amnion (about days 8-12)", "Before fertilisation"], "answer": 2, "why": "Early splitting (days 0-3) gives two chorions and two amnions; days 4-8 one chorion, two amnions."}]}, {"id": "y1-histo1-sina-mock", "subject": "histo1", "title": "Sina mock exam: Histology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering the four basic tissues and the digestive and urinary systems. One answer per question, each with a short explanation.", "questions": [{"q": "The epithelium lining the urinary bladder is:", "options": ["Simple squamous", "Transitional (urothelium)", "Stratified squamous keratinised", "Simple columnar"], "answer": 1, "why": "Urothelium stretches; its umbrella cells protect against urine.", "slides": [{"src": "files/slides/histo1-urinary/33.jpg", "lec": "Histology of the urinary system", "n": 33}]}, {"q": "Simple squamous epithelium lines:", "options": ["The small intestine", "Blood vessels (endothelium) and alveoli", "The oesophagus", "The skin"], "answer": 1, "why": "Thin cells allow diffusion and filtration.", "slides": [{"src": "files/slides/histo1-epithelium/33.jpg", "lec": "Epithelial tissue", "n": 33}]}, {"q": "The epithelium of the trachea is:", "options": ["Simple cuboidal", "Stratified squamous", "Transitional", "Pseudostratified ciliated columnar with goblet cells"], "answer": 3, "why": "Respiratory epithelium.", "slides": [{"src": "files/slides/histo1-epithelium/33.jpg", "lec": "Epithelial tissue", "n": 33}]}, {"q": "Tight junctions (zonula occludens):", "options": ["Seal the space between neighbouring cells", "Link intermediate filaments", "Allow ions to pass between cells", "Anchor cells to the basement membrane"], "answer": 0, "why": "Gap junctions pass ions; desmosomes link intermediate filaments; hemidesmosomes anchor to the basement membrane."}, {"q": "The main cell of connective tissue proper, which makes collagen, is:", "options": ["The adipocyte", "The mast cell", "The plasma cell", "The fibroblast"], "answer": 3, "why": "Mast cells release histamine; plasma cells make antibodies.", "slides": [{"src": "files/slides/histo1-connective/10.jpg", "lec": "Connective tissue", "n": 10}]}, {"q": "Type I collagen is the main collagen of:", "options": ["Hyaline cartilage", "Reticular fibres", "Bone, tendon and skin", "Basement membranes"], "answer": 2, "why": "Type II = cartilage; type III = reticular fibres; type IV = basement membranes.", "slides": [{"src": "files/slides/histo1-bone/20.jpg", "lec": "Bone", "n": 20}]}, {"q": "Hyaline cartilage:", "options": ["Is richly vascularised", "Forms the intervertebral disc annulus", "Is avascular and nourished by diffusion from the perichondrium", "Contains mainly type I collagen"], "answer": 2, "why": "Articular cartilage has no perichondrium. Fibrocartilage (type I collagen) forms the annulus fibrosus.", "slides": [{"src": "files/slides/histo1-cartilage/23.jpg", "lec": "Cartilage", "n": 23}]}, {"q": "Elastic cartilage is found in:", "options": ["The pubic symphysis", "The trachea rings", "The articular surfaces", "The external ear and epiglottis"], "answer": 3, "why": "Tracheal rings are hyaline; the pubic symphysis is fibrocartilage.", "slides": [{"src": "files/slides/histo1-cartilage/26.jpg", "lec": "Cartilage", "n": 26}]}, {"q": "Osteoclasts:", "options": ["Are trapped in lacunae", "Line the Haversian canals as stem cells", "Are multinucleated cells of monocyte origin that resorb bone", "Build bone matrix"], "answer": 2, "why": "Osteoblasts make osteoid; osteocytes sit in lacunae and communicate by canaliculi.", "slides": [{"src": "files/slides/histo1-bone/10.jpg", "lec": "Bone", "n": 10}]}, {"q": "The functional unit of compact bone is:", "options": ["The sarcomere", "The trabecula", "The lacuna", "The osteon (Haversian system)"], "answer": 3, "why": "Concentric lamellae around a central (Haversian) canal; Volkmann canals run across.", "slides": [{"src": "files/slides/histo1-bone/37.jpg", "lec": "Bone", "n": 37}]}, {"q": "Endochondral ossification forms:", "options": ["The clavicle entirely", "Most long bones, from a cartilage model", "Teeth", "The flat bones of the skull"], "answer": 1, "why": "Intramembranous ossification forms the flat bones of the skull and part of the clavicle.", "slides": [{"src": "files/slides/histo1-bone/29.jpg", "lec": "Bone", "n": 29}]}, {"q": "Neutrophils in a blood smear have:", "options": ["Dark blue granules hiding the nucleus", "A large round nucleus filling the cell", "Large orange-red granules and a bilobed nucleus", "A multilobed (3-5 lobes) nucleus and pale granules"], "answer": 3, "why": "Eosinophils: bilobed with red-orange granules; basophils: dark purple granules.", "slides": [{"src": "files/slides/histo1-blood/20.jpg", "lec": "Blood", "n": 20}]}, {"q": "Skeletal muscle fibres are:", "options": ["Branched, with one central nucleus", "Joined by intercalated discs", "Spindle-shaped and non-striated", "Long, multinucleated, striated, with peripheral nuclei"], "answer": 3, "why": "Cardiac: branched, central nucleus, intercalated discs. Smooth: spindle-shaped, no striations.", "slides": [{"src": "files/slides/histo1-muscle/51.jpg", "lec": "Muscle tissue", "n": 51}]}, {"q": "The sarcomere extends between:", "options": ["An A band and an I band", "Two M lines", "Two H zones", "Two Z lines (discs)"], "answer": 3, "why": "During contraction the I band and H zone shorten; the A band keeps its length.", "slides": [{"src": "files/slides/histo1-muscle/26.jpg", "lec": "Muscle tissue", "n": 26}]}, {"q": "Myelin in the central nervous system is formed by:", "options": ["Microglia", "Oligodendrocytes", "Astrocytes", "Schwann cells"], "answer": 1, "why": "One oligodendrocyte myelinates several axons; in the PNS one Schwann cell myelinates one internode.", "slides": [{"src": "files/slides/histo1-nervous/40.jpg", "lec": "Nervous tissue", "n": 40}]}, {"q": "Nissl bodies in neurons are:", "options": ["Clusters of rough endoplasmic reticulum and ribosomes", "Mitochondria", "Neurofilaments", "Lysosomes"], "answer": 0, "why": "They stain with basic dyes and are absent from the axon hillock.", "slides": [{"src": "files/slides/histo1-nervous/11.jpg", "lec": "Nervous tissue", "n": 11}]}, {"q": "The muscularis externa of most of the digestive tract has:", "options": ["One layer", "Inner circular and outer longitudinal layers", "Inner longitudinal and outer circular layers", "Three oblique layers everywhere"], "answer": 1, "why": "The stomach adds an inner oblique layer. The myenteric (Auerbach) plexus lies between the two layers.", "slides": [{"src": "files/slides/histo1-git/10.jpg", "lec": "Histology of the digestive system", "n": 10}]}, {"q": "Paneth cells are found:", "options": ["In the oesophageal glands", "In the colon surface epithelium", "In the gastric pits", "At the base of the intestinal crypts of Lieberkühn"], "answer": 3, "why": "They secrete lysozyme and defensins."}, {"q": "Brunner's glands are characteristic of:", "options": ["The duodenum (submucosa)", "The jejunum", "The colon", "The ileum"], "answer": 0, "why": "They secrete alkaline mucus to neutralise gastric acid.", "slides": [{"src": "files/slides/histo1-git/37.jpg", "lec": "Histology of the digestive system", "n": 37}]}, {"q": "Podocytes are found in:", "options": ["The loop of Henle", "The collecting duct", "The proximal tubule", "The visceral layer of Bowman's capsule"], "answer": 3, "why": "Their foot processes and filtration slits form part of the glomerular filtration barrier.", "slides": [{"src": "files/slides/histo1-urinary/18.jpg", "lec": "Histology of the urinary system", "n": 18}]}]}, {"id": "y1-bacterio1-sina-mock", "subject": "bacterio1", "title": "Sina mock exam: Bacteriology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering bacterial structure, genetics, antibiotics and the main pathogens of the course. One answer per question, each with a short explanation.", "questions": [{"q": "Gram-positive bacteria stain purple because they have:", "options": ["A thick peptidoglycan layer that keeps crystal violet", "An outer membrane with LPS", "Mycolic acids", "No cell wall"], "answer": 0, "why": "Gram-negatives have a thin peptidoglycan layer plus an outer membrane with LPS (endotoxin).", "slides": [{"src": "files/slides/bacterio1-structure/21.jpg", "lec": "Bacterial structure, nutrition and", "n": 21}]}, {"q": "Bacterial endospores:", "options": ["Are killed by boiling for 1 minute", "Are resistant dormant forms (e.g. Bacillus, Clostridium)", "Are found in Gram-negative cocci", "Are a means of reproduction"], "answer": 1, "why": "Autoclaving (121 °C) is needed to destroy them.", "slides": [{"src": "files/slides/bacterio1-structure/27.jpg", "lec": "Bacterial structure, nutrition and", "n": 27}]}, {"q": "Transfer of genes by a bacteriophage is called:", "options": ["Transduction", "Transformation", "Transposition", "Conjugation"], "answer": 0, "why": "Transformation = uptake of free DNA; conjugation = transfer through a pilus (plasmids).", "slides": [{"src": "files/slides/bacterio1-genetics/02.jpg", "lec": "Bacterial genetics", "n": 2}]}, {"q": "Endotoxin (LPS):", "options": ["Is heat-labile", "Is part of the outer membrane of Gram-negative bacteria; lipid A is the toxic part", "Is secreted by Gram-positive bacteria", "Is a protein that is easily turned into a toxoid"], "answer": 1, "why": "Exotoxins are secreted proteins and can be made into toxoids; endotoxin is heat-stable.", "slides": [{"src": "files/slides/bacterio1-enterobacteria-2/15.jpg", "lec": "Enterobacteriaceae II: Salmonella,", "n": 15}]}, {"q": "β-lactam antibiotics act by:", "options": ["Inhibiting cell-wall synthesis (binding penicillin-binding proteins)", "Inhibiting DNA gyrase", "Inhibiting protein synthesis at the 30S subunit", "Disrupting the cell membrane"], "answer": 0, "why": "Aminoglycosides and tetracyclines act on the 30S subunit; fluoroquinolones inhibit DNA gyrase.", "slides": [{"src": "files/slides/bacterio1-antibiotics/51.jpg", "lec": "Antibiotics", "n": 51}]}, {"q": "Methicillin resistance in Staphylococcus aureus is due to:", "options": ["Loss of porins", "β-lactamase only", "Efflux pumps", "An altered penicillin-binding protein (PBP2a, mecA gene)"], "answer": 3, "why": "PBP2a has low affinity for almost all β-lactams.", "slides": [{"src": "files/slides/bacterio1-antibiotics/26.jpg", "lec": "Antibiotics", "n": 26}]}, {"q": "Streptococcus pyogenes is:", "options": ["β-haemolytic group A, bacitracin-sensitive", "α-haemolytic, optochin-sensitive", "γ-haemolytic", "A Gram-negative diplococcus"], "answer": 0, "why": "S. pneumoniae is α-haemolytic and optochin-sensitive.", "slides": [{"src": "files/slides/bacterio1-pyogenes/10.jpg", "lec": "Streptococcus pyogenes", "n": 10}]}, {"q": "A non-suppurative complication of S. pyogenes pharyngitis is:", "options": ["Scarlet fever", "Acute rheumatic fever", "Necrotising fasciitis", "Impetigo"], "answer": 1, "why": "Rheumatic fever (after pharyngitis) and post-streptococcal glomerulonephritis are immune-mediated sequelae.", "slides": [{"src": "files/slides/bacterio1-pyogenes/18.jpg", "lec": "Streptococcus pyogenes", "n": 18}]}, {"q": "The main virulence factor of Streptococcus pneumoniae is:", "options": ["M protein", "Coagulase", "Endotoxin", "Its polysaccharide capsule"], "answer": 3, "why": "The capsule resists phagocytosis; vaccines target capsular polysaccharides.", "slides": [{"src": "files/slides/bacterio1-structure/20.jpg", "lec": "Bacterial structure, nutrition and", "n": 20}]}, {"q": "Haemophilus influenzae grows on chocolate agar because it needs:", "options": ["Cysteine", "Only X factor", "Charcoal", "X factor (haemin) and V factor (NAD)"], "answer": 3, "why": "Hib's polyribosyl-ribitol-phosphate capsule is the target of the conjugate vaccine.", "slides": [{"src": "files/slides/bacterio1-haemophilus/17.jpg", "lec": "Haemophilus influenzae type b", "n": 17}]}, {"q": "Mycobacterium tuberculosis is identified on a smear by:", "options": ["India ink", "Gram stain (Gram-positive cocci)", "Ziehl-Neelsen stain (acid-fast bacilli)", "Giemsa stain"], "answer": 2, "why": "Mycolic acids make the wall acid-fast.", "slides": [{"src": "files/slides/bacterio1-mycobacteria/19.jpg", "lec": "Mycobacteria and tuberculosis", "n": 19}]}, {"q": "The classic medium for culturing M. tuberculosis is:", "options": ["MacConkey agar", "Löwenstein-Jensen", "Blood agar", "Thayer-Martin"], "answer": 1, "why": "Growth is slow (3-6 weeks).", "slides": [{"src": "files/slides/bacterio1-mycobacteria/08.jpg", "lec": "Mycobacteria and tuberculosis", "n": 8}]}, {"q": "Chlamydia species are:", "options": ["Acid-fast bacilli", "Free-living bacteria", "Obligate intracellular bacteria with elementary and reticulate bodies", "Bacteria without any cell wall"], "answer": 2, "why": "The elementary body is infectious; the reticulate body divides inside the cell.", "slides": [{"src": "files/slides/bacterio1-chlamydia/05.jpg", "lec": "Chlamydia pneumoniae", "n": 5}]}, {"q": "Bordetella pertussis causes whooping cough mainly through:", "options": ["Spore formation", "Pertussis toxin and adhesins that act on the ciliated respiratory epithelium", "Invasion of the bloodstream", "A polysaccharide capsule"], "answer": 1, "why": "Pertussis toxin raises cAMP (ADP-ribosylates Gi); the paroxysmal stage gives the 'whoop'.", "slides": [{"src": "files/slides/bacterio1-bordetella/04.jpg", "lec": "Bordetella pertussis", "n": 4}]}, {"q": "Mycoplasma pneumoniae is not treated by β-lactams because it:", "options": ["Produces β-lactamase", "Has no cell wall", "Is acid-fast", "Has a thick capsule"], "answer": 1, "why": "Macrolides or tetracyclines are used. Its membrane contains sterols."}, {"q": "Enterobacteriaceae are:", "options": ["Gram-negative bacilli, oxidase-negative, that ferment glucose", "Acid-fast", "Gram-positive cocci", "Obligate anaerobes"], "answer": 0, "why": "They also reduce nitrates to nitrites.", "slides": [{"src": "files/slides/bacterio1-enterobacteria-1/41.jpg", "lec": "Enterobacteriaceae I: E. coli and", "n": 41}]}, {"q": "A lactose-fermenting, pink colony on MacConkey agar is typical of:", "options": ["Shigella", "Salmonella", "Proteus", "Escherichia coli"], "answer": 3, "why": "Salmonella, Shigella and Proteus do not ferment lactose (pale colonies).", "slides": [{"src": "files/slides/bacterio1-enterobacteria-2/10.jpg", "lec": "Enterobacteriaceae II: Salmonella,", "n": 10}]}, {"q": "The most common cause of community urinary tract infection is:", "options": ["Proteus mirabilis", "Escherichia coli (uropathogenic)", "Klebsiella pneumoniae", "Salmonella Typhi"], "answer": 1, "why": "Proteus produces urease (alkaline urine, stones).", "slides": [{"src": "files/slides/bacterio1-enterobacteria-1/19.jpg", "lec": "Enterobacteriaceae I: E. coli and", "n": 19}]}, {"q": "Salmonella Typhi:", "options": ["Does not produce H2S", "Has animal reservoirs", "Infects only humans and causes typhoid fever", "Ferments lactose"], "answer": 2, "why": "Non-typhoidal Salmonella have animal reservoirs and cause gastroenteritis."}, {"q": "Proteus mirabilis is recognised in the laboratory by:", "options": ["Acid-fast staining", "Optochin sensitivity", "Swarming motility on blood agar and strong urease activity", "Need for X and V factors"], "answer": 2, "why": "Urease splits urea into ammonia, giving struvite stones.", "slides": [{"src": "files/slides/bacterio1-enterobacteria-1/10.jpg", "lec": "Enterobacteriaceae I: E. coli and", "n": 10}]}]}, {"id": "y1-term1-sina-mock", "subject": "term1", "title": "Sina mock exam: Medical Terminology", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering word parts and the cardiovascular, respiratory, digestive and endocrine terms. One answer per question, each with a short explanation.", "questions": [{"q": "When decoding a medical term, you usually start with:", "options": ["The first root", "The combining vowel", "The prefix", "The suffix"], "answer": 3, "why": "Start at the end (suffix), then the prefix, then the roots: gastr/itis = inflammation of the stomach.", "slides": [{"src": "files/slides/term1-intro/08.jpg", "lec": "Introduction to medical terminology", "n": 8}]}, {"q": "In 'gastr/o', the 'o' is:", "options": ["A root", "A combining vowel", "A prefix", "A suffix"], "answer": 1, "why": "Root + combining vowel = combining form.", "slides": [{"src": "files/slides/term1-intro/25.jpg", "lec": "Introduction to medical terminology", "n": 25}]}, {"q": "Which statement about word parts is correct?", "options": ["A prefix always goes at the beginning of the term", "A combining vowel is kept before a suffix starting with a vowel", "A root can stand alone as a complete term", "A suffix is optional"], "answer": 0, "why": "The vowel is dropped before a suffix that begins with a vowel (gastr/itis, not gastro/itis).", "slides": [{"src": "files/slides/term1-intro/16.jpg", "lec": "Introduction to medical terminology", "n": 16}]}, {"q": "'Pericardiectomy' means:", "options": ["Incision into the heart muscle", "Inflammation around the heart", "Repair of a heart valve", "Surgical excision of all or part of the pericardium"], "answer": 3, "why": "peri- (around) + cardi (heart) + -ectomy (excision).", "slides": [{"src": "files/slides/term1-intro/11.jpg", "lec": "Introduction to medical terminology", "n": 11}]}, {"q": "The colour combining form 'cyan/o' means:", "options": ["White", "Black", "Blue", "Red"], "answer": 2, "why": "Cyanosis = bluish skin; erythr/o red, leuk/o white, melan/o black.", "slides": [{"src": "files/slides/term1-resp/27.jpg", "lec": "Respiratory system terminology", "n": 27}]}, {"q": "Gastrodynia and gastralgia both mean:", "options": ["Removal of the stomach", "Stomach inflammation", "Enlarged stomach", "Stomach pain"], "answer": 3, "why": "-dynia and -algia both mean pain.", "slides": [{"src": "files/slides/term1-gi/13.jpg", "lec": "Digestive system terminology", "n": 13}]}, {"q": "'Phleb/o' and 'ven/o' refer to:", "options": ["Veins", "Arteries", "Lymph vessels", "Valves"], "answer": 0, "why": "Phlebitis = inflammation of a vein.", "slides": [{"src": "files/slides/term1-cardio/29.jpg", "lec": "Cardiovascular system terminology", "n": 29}]}, {"q": "'Aortostenosis' means:", "options": ["Rupture of the aorta", "Narrowing of the aorta", "Hardening of the aorta", "Dilation of the aorta"], "answer": 1, "why": "-stenosis = narrowing.", "slides": [{"src": "files/slides/term1-cardio/13.jpg", "lec": "Cardiovascular system terminology", "n": 13}]}, {"q": "'Arteriosclerosis' means:", "options": ["Abnormal hardening of arterial walls", "Suturing of an artery", "A blood clot in an artery", "Inflammation of an arteriole"], "answer": 0, "why": "scler/o = hard; ather/o = fatty plaque (atheroma).", "slides": [{"src": "files/slides/term1-cardio/15.jpg", "lec": "Cardiovascular system terminology", "n": 15}]}, {"q": "'Thrombolysis' means:", "options": ["Measurement of blood pressure", "Breaking up of a blood clot", "Formation of a clot", "Removal of a vein"], "answer": 1, "why": "thromb/o clot + -lysis breakdown.", "slides": [{"src": "files/slides/term1-cardio/31.jpg", "lec": "Cardiovascular system terminology", "n": 31}]}, {"q": "The innermost layer lining the heart chambers and valves is the:", "options": ["Endocardium", "Epicardium", "Parietal pericardium", "Myocardium"], "answer": 0, "why": "endo- = within; the epicardium is the visceral pericardium.", "slides": [{"src": "files/slides/term1-cardio/68.jpg", "lec": "Cardiovascular system terminology", "n": 68}]}, {"q": "'Tachypnea' means:", "options": ["Slow breathing", "Rapid breathing", "Absence of breathing", "Normal breathing"], "answer": 1, "why": "Eupnea normal, bradypnea slow, tachypnea rapid (over 20/min), apnea absent.", "slides": [{"src": "files/slides/term1-resp/24.jpg", "lec": "Respiratory system terminology", "n": 24}]}, {"q": "'Epistaxis' is:", "options": ["Bluish skin", "Loss of voice", "A nosebleed", "Coughing up blood"], "answer": 2, "why": "Haemoptysis = coughing up blood; aphonia = loss of voice."}, {"q": "'Hypercapnia' means:", "options": ["Collapse of a lung", "Excess carbon dioxide in the blood", "Low blood oxygen", "Rapid breathing"], "answer": 1, "why": "capn = carbon dioxide; hypoxemia = low blood oxygen.", "slides": [{"src": "files/slides/term1-resp/27.jpg", "lec": "Respiratory system terminology", "n": 27}]}, {"q": "'Dysphonia' means:", "options": ["Difficulty swallowing", "Difficulty speaking (hoarseness)", "Difficulty breathing", "Indigestion"], "answer": 1, "why": "phon/o = voice. Dysphagia = difficulty swallowing; dyspnea = difficulty breathing.", "slides": [{"src": "files/slides/term1-resp/25.jpg", "lec": "Respiratory system terminology", "n": 25}]}, {"q": "A specialist of the ear, nose and throat is the:", "options": ["Nephrologist", "Pulmonologist", "Gastroenterologist", "Otolaryngologist"], "answer": 3, "why": "ot/o ear, laryng/o larynx."}, {"q": "'Sialorrhea' means:", "options": ["Dry mouth", "Inflammation of the gums", "Excessive flow of saliva", "Tongue pain"], "answer": 2, "why": "sial/o saliva + -rrhea flow; gingiv/o = gums.", "slides": [{"src": "files/slides/term1-gi/11.jpg", "lec": "Digestive system terminology", "n": 11}]}, {"q": "'Sublingual' means:", "options": ["Under the tongue", "Above the tongue", "Around the mouth", "Behind the teeth"], "answer": 0, "why": "lingu/o and gloss/o = tongue."}, {"q": "'Haematemesis' means:", "options": ["Blood in the urine", "Blood in the stool", "Vomiting blood", "Coughing up blood"], "answer": 2, "why": "-emesis = vomiting.", "slides": [{"src": "files/slides/term1-gi/26.jpg", "lec": "Digestive system terminology", "n": 26}]}, {"q": "'Dyspepsia' means:", "options": ["Loss of appetite", "Vomiting", "Difficulty swallowing", "Indigestion"], "answer": 3, "why": "-pepsia = digestion; -phagia = swallowing; -orexia = appetite.", "slides": [{"src": "files/slides/term1-gi/27.jpg", "lec": "Digestive system terminology", "n": 27}]}, {"q": "'Cholecystectomy' is:", "options": ["Removal of the liver", "Incision into the colon", "Removal of the gallbladder", "Stones in the bile duct"], "answer": 2, "why": "cholecyst/o = gallbladder; cholelithiasis = gallstones.", "slides": [{"src": "files/slides/term1-gi/76.jpg", "lec": "Digestive system terminology", "n": 76}]}, {"q": "'Homeostasis' means:", "options": ["Rapid hormonal change", "Excess hormone secretion", "Blood clotting", "A constant internal environment"], "answer": 3, "why": "home/o constant + -stasis control.", "slides": [{"src": "files/slides/term1-endocrine/04.jpg", "lec": "Endocrine system terminology", "n": 4}]}, {"q": "Which hormone is stored and released by the posterior pituitary?", "options": ["ACTH", "TSH", "Growth hormone", "Antidiuretic hormone (ADH)"], "answer": 3, "why": "The posterior lobe stores hypothalamic ADH and oxytocin.", "slides": [{"src": "files/slides/term1-endocrine/40.jpg", "lec": "Endocrine system terminology", "n": 40}]}, {"q": "'Adrenocorticotropic' hormone stimulates:", "options": ["The ovaries", "The thyroid", "The pancreatic islets", "The adrenal cortex"], "answer": 3, "why": "adren/o + cortic/o (cortex) + trop (change, stimulate).", "slides": [{"src": "files/slides/term1-endocrine/14.jpg", "lec": "Endocrine system terminology", "n": 14}]}, {"q": "The combining form 'somat/o' (as in somatotropic hormone) means:", "options": ["Sugar", "Sleep", "Milk", "Body"], "answer": 3, "why": "Somatotropin = growth hormone. lact/o = milk; somn/o = sleep; glyc/o = sugar."}]}, {"id": "y1-pubhealth1-sina-mock", "subject": "pubhealth1", "title": "Sina mock exam: Public Health", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering health, determinants, prevention and promotion, indicators and epidemiology. One answer per question, each with a short explanation.", "questions": [{"q": "The WHO (1948) defines health as:", "options": ["A state of complete physical, mental and social well-being, and not merely the absence of disease or infirmity", "Access to a doctor", "Physical fitness only", "The absence of disease"], "answer": 0, "why": "WHO Constitution, 1948.", "slides": [{"src": "files/slides/pubhealth1-intro/10.jpg", "lec": "Introduction to public health", "n": 10}]}, {"q": "Winslow defined public health as the science and art of:", "options": ["Preventing disease, prolonging life and promoting health through organised efforts of society", "Treating individual patients", "Training doctors", "Building hospitals"], "answer": 0, "why": "The definition stresses organised, collective efforts and informed choices.", "slides": [{"src": "files/slides/pubhealth1-intro/12.jpg", "lec": "Introduction to public health", "n": 12}]}, {"q": "Compared with clinical medicine, the public health approach:", "options": ["Gives all power to the doctor", "Targets only sick people who consult", "Ignores costs", "Targets the whole population, including people who do not consult, and takes costs into account"], "answer": 3, "why": "Clinical care is individual, at the moment of contact; public health is population-wide and needs participation.", "slides": [{"src": "files/slides/pubhealth1-intro/16.jpg", "lec": "Introduction to public health", "n": 16}]}, {"q": "The case of an anxious teenager with a hand wound shows that good care should be:", "options": ["Delayed until morning", "Limited to antibiotics", "Holistic: clinical, psychological and social, by a multidisciplinary team", "Purely surgical"], "answer": 2, "why": "The lecture uses it to show care beyond the wound itself.", "slides": [{"src": "files/slides/pubhealth1-intro/09.jpg", "lec": "Introduction to public health", "n": 9}]}, {"q": "Which is a NON-modifiable determinant of cardiovascular disease?", "options": ["High LDL cholesterol", "Physical inactivity", "Age", "Smoking"], "answer": 2, "why": "Age, sex, family history and ethnic origin cannot be changed.", "slides": [{"src": "files/slides/pubhealth1-determinants/31.jpg", "lec": "Determinants of health", "n": 31}]}, {"q": "A family history counted as a cardiovascular risk factor is:", "options": ["A father with a heart attack before 55 or a mother before 65", "Any relative with high blood pressure", "A sibling with asthma", "A grandparent who died after 80"], "answer": 0, "why": "Premature disease in a first-degree relative.", "slides": [{"src": "files/slides/pubhealth1-determinants/07.jpg", "lec": "Determinants of health", "n": 7}]}, {"q": "Protective factors are:", "options": ["Non-modifiable genetic risks", "Attributes (skills, strengths, resources) that shield people from developing or worsening health problems", "Hospital equipment", "Factors that always cause disease"], "answer": 1, "why": "They help people cope; risk factors work the other way.", "slides": [{"src": "files/slides/pubhealth1-determinants/12.jpg", "lec": "Determinants of health", "n": 12}]}, {"q": "The recommended minimum physical activity in the lecture is:", "options": ["5 hours per day", "10 minutes per day of walking only", "30 minutes per week", "150 minutes per week of moderate-to-vigorous activity"], "answer": 3, "why": "Physical inactivity is a modifiable risk factor.", "slides": [{"src": "files/slides/pubhealth1-determinants/08.jpg", "lec": "Determinants of health", "n": 8}]}, {"q": "Immunisation and health education are examples of:", "options": ["Secondary prevention", "Primary prevention", "Palliative care", "Tertiary prevention"], "answer": 1, "why": "Primary prevention acts before disease to lower incidence; it is the most cost-effective.", "slides": [{"src": "files/slides/pubhealth1-approaches/11.jpg", "lec": "Public health approaches: prevention", "n": 11}]}, {"q": "Cancer screening is an example of:", "options": ["Health promotion only", "Tertiary prevention", "Secondary prevention", "Primary prevention"], "answer": 2, "why": "Secondary prevention = early detection, ideally before clinical signs.", "slides": [{"src": "files/slides/pubhealth1-approaches/10.jpg", "lec": "Public health approaches: prevention", "n": 10}]}, {"q": "Rehabilitation and physiotherapy after a stroke are:", "options": ["Secondary prevention", "Primary prevention", "Not prevention", "Tertiary prevention"], "answer": 3, "why": "Tertiary prevention reduces chronic disability and recurrence.", "slides": [{"src": "files/slides/pubhealth1-approaches/14.jpg", "lec": "Public health approaches: prevention", "n": 14}]}, {"q": "Screening is justified when:", "options": ["No test exists", "The disease is rare and untreatable", "Only the patient asks for it", "The disease is frequent enough to cause excess mortality, an effective treatment exists, and mass early diagnosis is feasible"], "answer": 3, "why": "These are the conditions given in the lecture.", "slides": [{"src": "files/slides/pubhealth1-approaches/13.jpg", "lec": "Public health approaches: prevention", "n": 13}]}, {"q": "The Ottawa Charter (1986) defined health promotion as:", "options": ["Vaccination campaigns", "Screening programmes", "Building more hospitals", "The process of enabling people to increase control over their health and its determinants"], "answer": 3, "why": "Health promotion is participatory, unlike the more directive prevention model.", "slides": [{"src": "files/slides/pubhealth1-approaches/16.jpg", "lec": "Public health approaches: prevention", "n": 16}]}, {"q": "A health indicator is:", "options": ["A type of vaccine", "A hospital", "A clinical symptom", "A quantitative measure reflecting a health condition, trend or factor in a population"], "answer": 3, "why": "Examples: incidence, immunisation coverage, life expectancy.", "slides": [{"src": "files/slides/pubhealth1-indicators/03.jpg", "lec": "Health indicators and measures of", "n": 3}]}, {"q": "Prevalence measures:", "options": ["Existing cases in a population at a given time", "The speed of new infections", "New cases over a period", "Deaths per year"], "answer": 0, "why": "Incidence = new cases over time; prevalence = all existing cases.", "slides": [{"src": "files/slides/pubhealth1-indicators/13.jpg", "lec": "Health indicators and measures of", "n": 13}]}, {"q": "9 new cases of diabetes in 3,000 people followed for 2 years gives an incidence rate of:", "options": ["9 per 1,000 person-years", "0.3%", "1.5 per 1,000 person-years", "3 per 1,000 person-years"], "answer": 2, "why": "9 / (3,000 × 2) = 1.5 per 1,000 person-years.", "slides": [{"src": "files/slides/pubhealth1-indicators/11.jpg", "lec": "Health indicators and measures of", "n": 11}]}, {"q": "A male:female ratio of 12:11 is an example of a:", "options": ["Incidence", "Proportion", "Rate", "Ratio"], "answer": 3, "why": "A ratio divides one quantity by another; a proportion is a fraction of the whole.", "slides": [{"src": "files/slides/pubhealth1-indicators/10.jpg", "lec": "Health indicators and measures of", "n": 10}]}, {"q": "For cervical cancer, the population at risk should include:", "options": ["Only women", "Only smokers", "Only children", "The whole population"], "answer": 0, "why": "The denominator must include only those who can develop the disease.", "slides": [{"src": "files/slides/pubhealth1-indicators/22.jpg", "lec": "Health indicators and measures of", "n": 22}]}, {"q": "The DALY is:", "options": ["A ratio of births to deaths", "A composite measure: disability-adjusted life years", "A count of deaths", "A hospital indicator"], "answer": 1, "why": "It combines years of life lost and years lived with disability.", "slides": [{"src": "files/slides/pubhealth1-indicators/07.jpg", "lec": "Health indicators and measures of", "n": 7}]}, {"q": "In a study of smoking and lung cancer, smoking is the:", "options": ["Outcome (dependent variable)", "Exposure (independent variable)", "Indicator", "Confounder by definition"], "answer": 1, "why": "Lung cancer is the outcome.", "slides": [{"src": "files/slides/pubhealth1-indicators/08.jpg", "lec": "Health indicators and measures of", "n": 8}]}, {"q": "Epidemiology is the study of:", "options": ["Bacteria only", "The distribution and determinants of health-related states in specified populations, and its application to control health problems", "Individual patients' treatment", "Hospital management"], "answer": 1, "why": "J. Last, 1988.", "slides": [{"src": "files/slides/pubhealth1-epidemiology/24.jpg", "lec": "Introduction to epidemiology", "n": 24}]}, {"q": "The 'distribution' part of epidemiology refers to:", "options": ["Time, person and place", "Hospital beds", "Drug delivery", "Genes only"], "answer": 0, "why": "Determinants are the causes (biological, social, behavioural, etc.)."}, {"q": "James Lind (1747) is known for:", "options": ["The smoking-lung cancer study", "The London cholera map", "Bills of mortality", "One of the first controlled clinical trials, on scurvy"], "answer": 3, "why": "Sailors given citrus fruit recovered.", "slides": [{"src": "files/slides/pubhealth1-epidemiology/10.jpg", "lec": "Introduction to epidemiology", "n": 10}]}, {"q": "John Snow is known for:", "options": ["Investigating the London (Soho) cholera outbreaks and linking them to water", "Inventing vital statistics", "Discovering penicillin", "The first vaccine"], "answer": 0, "why": "William Farr is the father of vital statistics; Graunt studied the bills of mortality.", "slides": [{"src": "files/slides/pubhealth1-epidemiology/14.jpg", "lec": "Introduction to epidemiology", "n": 14}]}, {"q": "Ibn al-Khatib (14th century) described:", "options": ["The circulation of blood", "Transmission of plague by contagion", "Scurvy treatment", "The smallpox vaccine"], "answer": 1, "why": "During the Black Death in al-Andalus, centuries before Pasteur.", "slides": [{"src": "files/slides/pubhealth1-epidemiology/08.jpg", "lec": "Introduction to epidemiology", "n": 8}]}]}, {"id": "y1-genetics1-sina-mock", "subject": "genetics1", "title": "Sina mock exam: Genetics", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering nucleic acids, the genome, replication, transcription and RNA processing. One answer per question, each with a short explanation.", "questions": [{"q": "The central dogma of molecular biology is:", "options": ["DNA → protein → RNA", "Protein → RNA → DNA", "RNA → DNA → protein", "DNA → RNA → protein"], "answer": 3, "why": "Replication copies DNA, transcription makes RNA, translation makes protein.", "slides": [{"src": "files/slides/genetics1-transcription/05.jpg", "lec": "DNA transcription", "n": 5}]}, {"q": "A nucleotide is made of:", "options": ["Two bases and a sugar", "A sugar and a base only", "An amino acid and a phosphate", "A phosphate, a pentose sugar and a nitrogenous base"], "answer": 3, "why": "A nucleoside lacks the phosphate.", "slides": [{"src": "files/slides/genetics1-intro/11.jpg", "lec": "Introduction to molecular genetics:", "n": 11}]}, {"q": "The purines are:", "options": ["Adenine and thymine", "Uracil and cytosine", "Adenine and guanine", "Cytosine and thymine"], "answer": 2, "why": "Purines (two rings) pair with pyrimidines (one ring: C, T, U), keeping the helix width constant.", "slides": [{"src": "files/slides/genetics1-genome/78.jpg", "lec": "The human genome: DNA structure and", "n": 78}]}, {"q": "Thymine differs from uracil by:", "options": ["A missing oxygen", "A methyl group at position 5", "An extra amino group", "An extra ring"], "answer": 1, "why": "Thymine = 5-methyluracil.", "slides": [{"src": "files/slides/genetics1-intro/17.jpg", "lec": "Introduction to molecular genetics:", "n": 17}]}, {"q": "DNA carries a negative charge because of its:", "options": ["Bases", "Phosphate groups", "Hydrogen bonds", "Ribose"], "answer": 1, "why": "The phosphodiester backbone is negatively charged.", "slides": [{"src": "files/slides/genetics1-intro/19.jpg", "lec": "Introduction to molecular genetics:", "n": 19}]}, {"q": "Chargaff's rules state that in double-stranded DNA:", "options": ["A = T and G = C", "(G+C)/(A+T) = 1 in all species", "A + T = 50% always", "A = G and T = C"], "answer": 0, "why": "So (A+G)/(T+C) = 1, while the (G+C)/(A+T) ratio varies between species.", "slides": [{"src": "files/slides/genetics1-genome/07.jpg", "lec": "The human genome: DNA structure and", "n": 7}]}, {"q": "G≡C base pairs are held by:", "options": ["One hydrogen bond", "Three hydrogen bonds", "Two hydrogen bonds", "Covalent bonds"], "answer": 1, "why": "A=T has two; GC-rich DNA is more stable (higher Tm).", "slides": [{"src": "files/slides/genetics1-genome/13.jpg", "lec": "The human genome: DNA structure and", "n": 13}]}, {"q": "The common physiological form of DNA is:", "options": ["Triple helix", "B-DNA, right-handed, about 10 bp per turn", "A-DNA", "Z-DNA, left-handed"], "answer": 1, "why": "Z-DNA is left-handed and rare; A-DNA appears in dehydrated conditions and RNA-DNA hybrids.", "slides": [{"src": "files/slides/genetics1-genome/07.jpg", "lec": "The human genome: DNA structure and", "n": 7}]}, {"q": "In B-DNA, one helical turn measures about:", "options": ["2 µm", "3.4 nm", "0.34 nm", "34 nm"], "answer": 1, "why": "10 bp per turn, 0.34 nm between consecutive base pairs.", "slides": [{"src": "files/slides/genetics1-genome/18.jpg", "lec": "The human genome: DNA structure and", "n": 18}]}, {"q": "The first truly complete (telomere-to-telomere) human genome was published in:", "options": ["2003", "1953", "2022", "2001"], "answer": 2, "why": "The HGP gave drafts in 2001 and 'completion' in 2003; T2T filled the gaps in 2022.", "slides": [{"src": "files/slides/genetics1-genome/20.jpg", "lec": "The human genome: DNA structure and", "n": 20}]}, {"q": "DNA replication is semi-conservative, as shown by:", "options": ["Meselson and Stahl", "Griffith", "Watson and Crick", "Chargaff"], "answer": 0, "why": "Density-gradient centrifugation with heavy and light nitrogen.", "slides": [{"src": "files/slides/genetics1-replication/05.jpg", "lec": "DNA replication", "n": 5}]}, {"q": "DNA polymerases synthesise DNA in the direction:", "options": ["Both directions equally", "5′ → 3′", "3′ → 5′", "Only from the centre outward"], "answer": 1, "why": "They add nucleotides to a free 3′-OH.", "slides": [{"src": "files/slides/genetics1-intro/24.jpg", "lec": "Introduction to molecular genetics:", "n": 24}]}, {"q": "In eukaryotes, replication origins are:", "options": ["One per chromosome", "Many per chromosome", "Absent", "Only at telomeres"], "answer": 1, "why": "Bacteria have a single origin; eukaryotic chromosomes have many, about 40 kb apart.", "slides": [{"src": "files/slides/genetics1-replication/07.jpg", "lec": "DNA replication", "n": 7}]}, {"q": "The enzyme that unwinds DNA at the replication fork is:", "options": ["Topoisomerase I", "Ligase", "Helicase", "Primase"], "answer": 2, "why": "Helicase uses ATP to break hydrogen bonds; topoisomerases relieve supercoiling ahead of the fork.", "slides": [{"src": "files/slides/genetics1-replication/12.jpg", "lec": "DNA replication", "n": 12}]}, {"q": "Single-strand binding proteins (RPA):", "options": ["Cut both DNA strands", "Stabilise and protect single-stranded DNA", "Join Okazaki fragments", "Make RNA primers"], "answer": 1, "why": "Primase makes primers; ligase joins fragments.", "slides": [{"src": "files/slides/genetics1-replication/13.jpg", "lec": "DNA replication", "n": 13}]}, {"q": "Type II topoisomerases (gyrase in bacteria):", "options": ["Cut both strands using ATP", "Synthesise primers", "Cut one strand without ATP", "Proofread DNA"], "answer": 0, "why": "Type I cuts one strand and needs no ATP.", "slides": [{"src": "files/slides/genetics1-replication/14.jpg", "lec": "DNA replication", "n": 14}]}, {"q": "The eukaryotic polymerase that synthesises the leading strand is:", "options": ["Pol γ", "Pol α", "Pol ε", "Pol β"], "answer": 2, "why": "Pol δ makes the lagging strand; Pol α-primase starts synthesis; Pol β repairs; Pol γ is mitochondrial.", "slides": [{"src": "files/slides/genetics1-replication/20.jpg", "lec": "DNA replication", "n": 20}]}, {"q": "Okazaki fragments are found on:", "options": ["The lagging strand", "mRNA", "The leading strand", "Both strands equally"], "answer": 0, "why": "The lagging strand is made discontinuously, away from the fork.", "slides": [{"src": "files/slides/genetics1-replication/20.jpg", "lec": "DNA replication", "n": 20}]}, {"q": "The melting temperature (Tm) of DNA rises with:", "options": ["Higher GC content, longer length and more cations", "More AT pairs", "Lower GC content", "Lower salt"], "answer": 0, "why": "Tm = temperature at which 50% of base pairs are separated.", "slides": [{"src": "files/slides/genetics1-transcription/10.jpg", "lec": "DNA transcription", "n": 10}]}, {"q": "Single-stranded DNA absorbs more UV light at 260 nm. This is the:", "options": ["Renaturation", "Hypochromic effect", "Melting point", "Hyperchromic effect"], "answer": 3, "why": "Unstacked bases absorb more UV.", "slides": [{"src": "files/slides/genetics1-transcription/10.jpg", "lec": "DNA transcription", "n": 10}]}, {"q": "During transcription, the template strand is read:", "options": ["5′ → 3′", "In both directions", "Only at the poly(A) site", "3′ → 5′"], "answer": 3, "why": "RNA is made 5′ → 3′ and matches the coding (sense) strand, with U for T.", "slides": [{"src": "files/slides/genetics1-transcription/11.jpg", "lec": "DNA transcription", "n": 11}]}, {"q": "RNA polymerase II transcribes:", "options": ["rRNA (28S, 18S, 5.8S)", "Mitochondrial DNA", "tRNA and 5S rRNA", "mRNA"], "answer": 3, "why": "Pol I = large rRNAs (nucleolus); Pol III = tRNA and 5S rRNA.", "slides": [{"src": "files/slides/genetics1-genome/68.jpg", "lec": "The human genome: DNA structure and", "n": 68}]}, {"q": "The 5′ cap of eukaryotic mRNA is:", "options": ["A ribosome", "A poly(A) tail", "An intron", "A 7-methylguanosine joined by a 5′-5′ triphosphate bond"], "answer": 3, "why": "It protects from 5′ exonucleases and helps export and translation initiation.", "slides": [{"src": "files/slides/genetics1-rna-processing/07.jpg", "lec": "Post-transcriptional RNA processing", "n": 7}]}, {"q": "The poly(A) tail is added after cleavage downstream of the signal:", "options": ["AUG", "GU-AG", "TATA", "AAUAAA"], "answer": 3, "why": "Poly(A) polymerase adds about 200 adenines without a template.", "slides": [{"src": "files/slides/genetics1-rna-processing/08.jpg", "lec": "Post-transcriptional RNA processing", "n": 8}]}, {"q": "During splicing, the branch-point adenine forms:", "options": ["A cap", "An Okazaki fragment", "A poly(A) tail", "A lariat"], "answer": 3, "why": "Two transesterifications by the spliceosome (snRNPs U1, U2, U4/U6, U5) remove the intron as a lariat.", "slides": [{"src": "files/slides/genetics1-rna-processing/12.jpg", "lec": "Post-transcriptional RNA processing", "n": 12}]}]}, {"id": "y1-cellbio1-sina-mock", "subject": "cellbio1", "title": "Sina mock exam: Cell Biology", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering study methods, the plasma membrane, the cytoskeleton, the cell cycle and the nucleus. One answer per question, each with a short explanation.", "questions": [{"q": "The microscope used to observe living, unstained cultured cells (e.g. embryos in assisted reproduction) is the:", "options": ["Transmission electron microscope", "Inverted microscope with phase-contrast optics", "Scanning electron microscope", "Fluorescence microscope"], "answer": 1, "why": "Its lamp is on top and the objective under the stage.", "slides": [{"src": "files/slides/cellbio1-methods/22.jpg", "lec": "Cell study methods: microscopy,", "n": 22}]}, {"q": "The scanning electron microscope (SEM) gives:", "options": ["Fluorescent labels", "Images of living cells in culture", "3D images of cell surfaces", "Sections of organelles"], "answer": 2, "why": "TEM shows ultrastructure (organelles) in thin sections.", "slides": [{"src": "files/slides/cellbio1-methods/28.jpg", "lec": "Cell study methods: microscopy,", "n": 28}]}, {"q": "Electron microscopes need a vacuum pump because:", "options": ["It focuses light", "It stains the sample", "It cools the specimen", "Electrons would be deflected by air molecules"], "answer": 3, "why": "They also use magnetic lenses instead of glass lenses.", "slides": [{"src": "files/slides/cellbio1-methods/25.jpg", "lec": "Cell study methods: microscopy,", "n": 25}]}, {"q": "The maximum useful magnification of the light microscope is about:", "options": ["100×", "1,000,000×", "100,000×", "1,000×"], "answer": 3, "why": "The TEM reaches about 100,000×, enough to show organelles.", "slides": [{"src": "files/slides/cellbio1-methods/24.jpg", "lec": "Cell study methods: microscopy,", "n": 24}]}, {"q": "In the light microscope, the lens that focuses light onto the specimen is the:", "options": ["Eyepiece", "Magnetic lens", "Condenser", "Objective"], "answer": 2, "why": "Objectives and eyepiece magnify the image.", "slides": [{"src": "files/slides/cellbio1-methods/31.jpg", "lec": "Cell study methods: microscopy,", "n": 31}]}, {"q": "The plasma membrane is described as:", "options": ["A rigid symmetric bilayer", "An asymmetric fluid mosaic", "A single lipid layer", "A protein sheet"], "answer": 1, "why": "Components move (fluid), form a mosaic, and sugars are only on the outer face (asymmetric).", "slides": [{"src": "files/slides/cellbio1-membrane/07.jpg", "lec": "The plasma membrane: structure,", "n": 7}]}, {"q": "Membrane carbohydrates are found:", "options": ["On both faces equally", "Only on the cytoplasmic face", "Inside the bilayer core", "Only on the extracellular face, forming the glycocalyx"], "answer": 3, "why": "As glycolipids and glycoproteins, with antigenic and protective roles.", "slides": [{"src": "files/slides/cellbio1-membrane/07.jpg", "lec": "The plasma membrane: structure,", "n": 7}]}, {"q": "Cholesterol in the plasma membrane:", "options": ["Is a peripheral protein", "Forms ion channels", "Increases permeability", "Sits between phospholipids and limits permeability"], "answer": 3, "why": "About 25% of membrane lipids in the lecture.", "slides": [{"src": "files/slides/cellbio1-membrane/05.jpg", "lec": "The plasma membrane: structure,", "n": 5}]}, {"q": "Transmembrane proteins such as pumps and channels are:", "options": ["Peripheral proteins", "Cytoskeletal proteins", "Glycolipids", "Integral (amphipathic) proteins"], "answer": 3, "why": "Peripheral proteins (e.g. clathrin, G proteins) sit on one face.", "slides": [{"src": "files/slides/cellbio1-membrane/06.jpg", "lec": "The plasma membrane: structure,", "n": 6}]}, {"q": "O₂ and CO₂ cross the plasma membrane by:", "options": ["Simple diffusion", "Endocytosis", "Active transport", "Facilitated diffusion through GLUT4"], "answer": 0, "why": "Small, uncharged molecules and gases diffuse directly through the bilayer.", "slides": [{"src": "files/slides/cellbio1-membrane/13.jpg", "lec": "The plasma membrane: structure,", "n": 13}]}, {"q": "Glucose entry through GLUT4 is an example of:", "options": ["Facilitated diffusion by a carrier protein", "Phagocytosis", "Simple diffusion", "Primary active transport"], "answer": 0, "why": "Passive, down the gradient, with a conformational change of the carrier.", "slides": [{"src": "files/slides/cellbio1-membrane/17.jpg", "lec": "The plasma membrane: structure,", "n": 17}]}, {"q": "Transport that moves ions against their gradient using ATP is:", "options": ["Filtration", "Active transport (e.g. the Na⁺/K⁺ pump)", "Osmosis", "Simple diffusion"], "answer": 1, "why": "Passive transport needs no ATP.", "slides": [{"src": "files/slides/cellbio1-membrane/12.jpg", "lec": "The plasma membrane: structure,", "n": 12}]}, {"q": "The three cytoskeleton filaments in increasing diameter are:", "options": ["Actin, microtubules, intermediate filaments", "Intermediate filaments, actin, microtubules", "Actin microfilaments, intermediate filaments, microtubules", "Microtubules, intermediate filaments, actin"], "answer": 2, "why": "Actin 5-8 nm, intermediate filaments 8-10 nm, microtubules 20-30 nm.", "slides": [{"src": "files/slides/cellbio1-cytoskeleton/04.jpg", "lec": "The cytosol and the cytoskeleton", "n": 4}]}, {"q": "The complex that nucleates actin filaments is:", "options": ["γ-TuRC", "MAP2", "CapZ", "ARP2/3"], "answer": 3, "why": "CapZ stops polymerisation; γ-TuRC nucleates microtubules.", "slides": [{"src": "files/slides/cellbio1-cytoskeleton/17.jpg", "lec": "The cytosol and the cytoskeleton", "n": 17}]}, {"q": "The contractile ring of cytokinesis is made of:", "options": ["Lamins", "Microtubules", "Actin and myosin II", "Keratin"], "answer": 2, "why": "Actin also forms microvilli and the cell cortex."}, {"q": "A microtubule is made of:", "options": ["Lamin A, B and C", "13 protofilaments of α/β-tubulin dimers", "Keratin tetramers", "Two twisted actin chains"], "answer": 1, "why": "They assemble on the γ-tubulin ring complex.", "slides": [{"src": "files/slides/cellbio1-cytoskeleton/25.jpg", "lec": "The cytosol and the cytoskeleton", "n": 25}]}, {"q": "The small G protein involved in vesicle traffic is:", "options": ["Ran", "Rab", "Ras", "Rho"], "answer": 1, "why": "Ran = nuclear transport; Ras = signalling; Rho = tension.", "slides": [{"src": "files/slides/cellbio1-cytoskeleton/22.jpg", "lec": "The cytosol and the cytoskeleton", "n": 22}]}, {"q": "Cells that stop dividing permanently, like neurons, stay in:", "options": ["G1", "S", "G2", "G0"], "answer": 3, "why": "They leave the cycle into G0.", "slides": [{"src": "files/slides/cellbio1-cycle-nucleus/03.jpg", "lec": "The cell cycle and the nucleus", "n": 3}]}, {"q": "The G1/S checkpoint (restriction point) checks mainly:", "options": ["Chromosome attachment to the spindle", "Cytokinesis", "Whether DNA replication is complete", "Whether the environment is favourable and the cell is large enough"], "answer": 3, "why": "G2/M checks DNA replication; the metaphase checkpoint checks spindle attachment.", "slides": [{"src": "files/slides/cellbio1-cycle-nucleus/05.jpg", "lec": "The cell cycle and the nucleus", "n": 5}]}, {"q": "p53 and pRb are:", "options": ["Histones", "Cyclins", "Tumour suppressors controlling cell-cycle checkpoints", "Oncogenes"], "answer": 2, "why": "Their loss lets damaged cells keep dividing.", "slides": [{"src": "files/slides/cellbio1-cycle-nucleus/06.jpg", "lec": "The cell cycle and the nucleus", "n": 6}]}, {"q": "Progression through the cell cycle is driven by:", "options": ["Cyclin/CDK complexes whose activity oscillates", "Histones", "Lamins", "Tubulin"], "answer": 0, "why": "Inhibitors include p16, p21, p27 and Wee1.", "slides": [{"src": "files/slides/cellbio1-cycle-nucleus/10.jpg", "lec": "The cell cycle and the nucleus", "n": 10}]}, {"q": "The outer nuclear membrane is:", "options": ["Lined by the nuclear lamina", "Made of keratin", "Continuous with the rough endoplasmic reticulum and carries ribosomes", "Free of pores"], "answer": 2, "why": "The inner membrane is lined by the lamina.", "slides": [{"src": "files/slides/cellbio1-cycle-nucleus/24.jpg", "lec": "The cell cycle and the nucleus", "n": 24}]}, {"q": "Progeria is due to a mutation in:", "options": ["Histone H1", "Actin", "Lamin A", "Tubulin"], "answer": 2, "why": "The nucleus is deformed because chromatin attaches poorly to the lamina."}, {"q": "A nucleosome core is made of DNA wrapped around:", "options": ["Two histones", "Lamins", "Ribosomes", "A histone octamer (2 each of H2A, H2B, H3, H4)"], "answer": 3, "why": "Like beads on a string.", "slides": [{"src": "files/slides/cellbio1-cycle-nucleus/18.jpg", "lec": "The cell cycle and the nucleus", "n": 18}]}, {"q": "Euchromatin is:", "options": ["Decondensed and transcriptionally active", "Found only in bacteria", "Found only in mitosis", "Condensed and silent"], "answer": 0, "why": "Heterochromatin is condensed and mostly silent.", "slides": [{"src": "files/slides/cellbio1-cycle-nucleus/14.jpg", "lec": "The cell cycle and the nucleus", "n": 14}]}]}, {"id": "y1-physics1-sina-mock", "subject": "physics1", "title": "Sina mock exam: Physics", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering units and uncertainties, states of matter, water and solutions, gases and energetics. One answer per question, each with a short explanation.", "questions": [{"q": "Which is NOT one of the 7 SI base quantities?", "options": ["Length (m)", "Luminous intensity (cd)", "Amount of substance (mol)", "Force (N)"], "answer": 3, "why": "The newton is derived: N = kg·m·s⁻².", "slides": [{"src": "files/slides/physics1-units/10.jpg", "lec": "Quantities, units and measurement", "n": 10}]}, {"q": "The pascal equals:", "options": ["J·kg⁻¹", "kg·m·s⁻²", "N·m⁻²", "J·s⁻¹"], "answer": 2, "why": "Pressure = force / area.", "slides": [{"src": "files/slides/physics1-gases/06.jpg", "lec": "Biophysics of the gaseous state", "n": 6}]}, {"q": "The dimensional equation of energy is:", "options": ["M·L²·T⁻²", "L·T⁻¹", "M·L·T⁻²", "M·L⁻¹·T⁻²"], "answer": 0, "why": "Force is M·L·T⁻²; pressure is M·L⁻¹·T⁻².", "slides": [{"src": "files/slides/physics1-units/17.jpg", "lec": "Quantities, units and measurement", "n": 17}]}, {"q": "Which quantity is intensive?", "options": ["Amount of substance", "Volume", "Temperature", "Mass"], "answer": 2, "why": "Intensive quantities (temperature, pressure, concentration) do not depend on the amount of matter.", "slides": [{"src": "files/slides/physics1-units/13.jpg", "lec": "Quantities, units and measurement", "n": 13}]}, {"q": "The prefix 'nano' means:", "options": ["10⁻¹²", "10⁻⁶", "10⁻⁹", "10⁻³"], "answer": 2, "why": "milli 10⁻³, micro 10⁻⁶, nano 10⁻⁹, pico 10⁻¹².", "slides": [{"src": "files/slides/physics1-units/15.jpg", "lec": "Quantities, units and measurement", "n": 15}]}, {"q": "The gray (Gy) is the unit of:", "options": ["Radioactive activity", "Power", "Electric charge", "Absorbed dose (J·kg⁻¹)"], "answer": 3, "why": "Activity is in becquerel; charge in coulomb.", "slides": [{"src": "files/slides/physics1-units/11.jpg", "lec": "Quantities, units and measurement", "n": 11}]}, {"q": "A badly calibrated instrument causes:", "options": ["Systematic errors that shift all results the same way", "Errors that cancel out on averaging", "No error", "Random errors"], "answer": 0, "why": "Random errors scatter results on both sides and are reduced by repeating measurements.", "slides": [{"src": "files/slides/physics1-units/32.jpg", "lec": "Quantities, units and measurement", "n": 32}]}, {"q": "Water dissolves ionic crystals well mainly because:", "options": ["It has a very high dielectric constant (78.5), weakening attraction between ions", "It has a low dielectric constant", "It is non-polar", "It is a gas"], "answer": 0, "why": "Coulomb force is inversely proportional to ε; ethanol (ε ≈ 24) keeps ions together more.", "slides": [{"src": "files/slides/physics1-water/07.jpg", "lec": "Biophysics of water and solutions", "n": 7}]}, {"q": "Hydration of Na⁺ in water is an example of:", "options": ["Ion-dipole interaction (solvation)", "Repulsion between electron clouds", "Van der Waals forces between neutral molecules", "Covalent bonding"], "answer": 0, "why": "Na⁺ is surrounded by the oxygen poles of water molecules.", "slides": [{"src": "files/slides/physics1-states/13.jpg", "lec": "Physical states of matter", "n": 13}]}, {"q": "The main cause that disperses molecules, increasing with temperature, is:", "options": ["Gravity", "Thermal agitation (Brownian motion)", "Van der Waals forces", "Coulomb attraction"], "answer": 1, "why": "Attractive forces gather particles; thermal agitation spreads them.", "slides": [{"src": "files/slides/physics1-states/15.jpg", "lec": "Physical states of matter", "n": 15}]}, {"q": "During melting of pure ice at 1 atm:", "options": ["No energy is exchanged", "Temperature drops", "Temperature rises steadily", "Temperature stays at 0 °C while solid and liquid coexist"], "answer": 3, "why": "The heat supplied is used for the change of state (latent heat).", "slides": [{"src": "files/slides/physics1-states/23.jpg", "lec": "Physical states of matter", "n": 23}]}, {"q": "Supercooling (superfusion) is:", "options": ["Direct change from solid to gas", "Freezing above 0 °C", "Boiling below 100 °C", "A liquid cooled below its freezing point without solidifying"], "answer": 3, "why": "It then solidifies suddenly."}, {"q": "A liquid:", "options": ["Has a fixed shape and volume", "Takes the shape of its container but has a fixed volume", "Is less dense than a gas", "Has no fixed volume and is highly compressible"], "answer": 1, "why": "A gas has neither fixed shape nor fixed volume.", "slides": [{"src": "files/slides/physics1-states/19.jpg", "lec": "Physical states of matter", "n": 19}]}, {"q": "Total body water is about:", "options": ["20% of body weight", "40% extracellular", "90% of body weight", "60% of body weight, about two-thirds intracellular"], "answer": 3, "why": "Intracellular ≈ 40%, extracellular ≈ 20% of body weight; higher in infants.", "slides": [{"src": "files/slides/physics1-water/04.jpg", "lec": "Biophysics of water and solutions", "n": 4}]}, {"q": "Ice floats on water because:", "options": ["Ice is denser than water", "Ice (≈ 0.91 g/cm³) is less dense than liquid water", "Water has low surface tension", "Ice has no hydrogen bonds"], "answer": 1, "why": "Hydrogen bonds hold ice in an open lattice.", "slides": [{"src": "files/slides/physics1-water/06.jpg", "lec": "Biophysics of water and solutions", "n": 6}]}, {"q": "The high specific heat of water (4.184 J/g·°C) means that it:", "options": ["Cannot dissolve salts", "Boils at a low temperature", "Buffers temperature changes in the body", "Heats up very fast"], "answer": 2, "why": "Thermal buffering.", "slides": [{"src": "files/slides/physics1-water/07.jpg", "lec": "Biophysics of water and solutions", "n": 7}]}, {"q": "For Ca²⁺, one mole equals:", "options": ["4 equivalents", "2 equivalents", "0.5 equivalent", "1 equivalent"], "answer": 1, "why": "1 mol = z Eq, with z = valence.", "slides": [{"src": "files/slides/physics1-water/10.jpg", "lec": "Biophysics of water and solutions", "n": 10}]}, {"q": "Molality is:", "options": ["Moles of solute per kilogram of solvent", "Moles of solute per litre of solution", "A dimensionless fraction", "Grams of solute per litre"], "answer": 0, "why": "Molarity is per litre of solution; summed, they give osmolality and osmolarity.", "slides": [{"src": "files/slides/physics1-water/13.jpg", "lec": "Biophysics of water and solutions", "n": 13}]}, {"q": "A solution contains 20 mEq/L Na⁺ and 45 mEq/L Cl⁻ with K⁺ as the only other ion. K⁺ is:", "options": ["20 mEq/L", "45 mEq/L", "65 mEq/L", "25 mEq/L"], "answer": 3, "why": "Electroneutrality: total cations = total anions, 45 − 20 = 25.", "slides": [{"src": "files/slides/physics1-water/18.jpg", "lec": "Biophysics of water and solutions", "n": 18}]}, {"q": "1 atm equals about:", "options": ["10 kPa", "133 Pa", "760 mmHg ≈ 101 kPa", "1 mmHg"], "answer": 2, "why": "1 mmHg = 133.3 Pa; 1 atm ≈ 10 m of water.", "slides": [{"src": "files/slides/physics1-gases/07.jpg", "lec": "Biophysics of the gaseous state", "n": 7}]}, {"q": "According to the fundamental law of hydrostatics, the pressure difference with depth is:", "options": ["ΔP = F·d", "ΔP = m·a", "ΔP = ρ·g·h", "ΔP = nRT"], "answer": 2, "why": "Pressure rises linearly with depth in a fluid at rest.", "slides": [{"src": "files/slides/physics1-gases/08.jpg", "lec": "Biophysics of the gaseous state", "n": 8}]}, {"q": "Boyle-Mariotte's law (constant n and T) states:", "options": ["V = nRT", "PV = constant", "P/T = constant", "V/T = constant"], "answer": 1, "why": "Charles: V ∝ T at constant P; Gay-Lussac: P/T constant at constant V.", "slides": [{"src": "files/slides/physics1-gases/11.jpg", "lec": "Biophysics of the gaseous state", "n": 11}]}, {"q": "One mole of ideal gas at 0 °C and 1 atm occupies:", "options": ["8.314 L", "1 L", "273 L", "22.4 L"], "answer": 3, "why": "Standard molar volume.", "slides": [{"src": "files/slides/physics1-gases/26.jpg", "lec": "Biophysics of the gaseous state", "n": 26}]}, {"q": "Lung volumes are reported under:", "options": ["STPD conditions", "ATPS conditions", "Vacuum", "BTPS conditions (37 °C, ambient pressure, saturated with water vapour)"], "answer": 3, "why": "Blood gas volumes often use STPD; spirometer readings are ATPS.", "slides": [{"src": "files/slides/physics1-gases/19.jpg", "lec": "Biophysics of the gaseous state", "n": 19}]}, {"q": "Dalton's law states that:", "options": ["PV = constant", "Pressure rises with depth", "The total pressure of a gas mixture is the sum of the partial pressures", "Gas dissolves in proportion to its partial pressure"], "answer": 2, "why": "Pᵢ = xᵢ × P total. (Dissolution in proportion to partial pressure is Henry's law.)", "slides": [{"src": "files/slides/physics1-gases/22.jpg", "lec": "Biophysics of the gaseous state", "n": 22}]}]}, {"id": "y1-biophys1-sina-mock", "subject": "biophys1", "title": "Sina mock exam: Biophysics", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering radioactivity, radiation-matter interactions, radiobiology, radiation protection and optics of the eye. One answer per question, each with a short explanation.", "questions": [{"q": "Isotopes are nuclides with:", "options": ["The same A, different Z", "The same Z, different A", "The same N, different Z", "The same nucleus in different energy states"], "answer": 1, "why": "Isobars: same A; isotones: same N; isomers: same nucleus, different energy (⁹⁹ᵐTc)."}, {"q": "The chemical properties of an element are set by:", "options": ["Its half-life", "Its number of neutrons", "Its mass number A", "Its atomic number Z"], "answer": 3, "why": "A sets physical (nuclear) properties.", "slides": [{"src": "files/slides/biophys1-radioactivity/12.jpg", "lec": "Radioactivity: general concepts", "n": 12}]}, {"q": "1 eV equals:", "options": ["931 MeV", "6.02 × 10²³ J", "0.511 MeV", "1.602 × 10⁻¹⁹ J"], "answer": 3, "why": "931 MeV corresponds to 1 u; 0.511 MeV to the electron mass.", "slides": [{"src": "files/slides/biophys1-radioactivity/14.jpg", "lec": "Radioactivity: general concepts", "n": 14}]}, {"q": "β⁻ decay happens in nuclei with:", "options": ["Excess neutrons: n → p + e⁻ + antineutrino", "Excess electrons", "Too few nucleons", "Excess protons"], "answer": 0, "why": "β⁻ emitters are used in targeted radionuclide therapy.", "slides": [{"src": "files/slides/biophys1-radioactivity/23.jpg", "lec": "Radioactivity: general concepts", "n": 23}]}, {"q": "β⁺ decay is possible only if the energy difference exceeds:", "options": ["0.511 MeV", "1.022 MeV", "931 MeV", "13.6 eV"], "answer": 1, "why": "Twice the electron rest mass (2 × 0.511 MeV).", "slides": [{"src": "files/slides/biophys1-radioactivity/18.jpg", "lec": "Radioactivity: general concepts", "n": 18}]}, {"q": "PET imaging detects:", "options": ["Auger electrons only", "Two 511 keV photons emitted at 180° after positron annihilation", "α particles", "Single β⁻ electrons"], "answer": 1, "why": "Coincidence detection of the two annihilation photons.", "slides": [{"src": "files/slides/biophys1-radioactivity/25.jpg", "lec": "Radioactivity: general concepts", "n": 25}]}, {"q": "In electron capture:", "options": ["An α particle is emitted", "Z increases by 1", "A proton captures an inner-shell electron and Z decreases by 1", "A positron is emitted"], "answer": 2, "why": "The vacancy is filled with emission of X-rays or Auger electrons.", "slides": [{"src": "files/slides/biophys1-radioactivity/27.jpg", "lec": "Radioactivity: general concepts", "n": 27}]}, {"q": "Indirectly ionising radiations include:", "options": ["Fission fragments", "X and γ photons and neutrons", "β⁻ and β⁺ particles", "α particles and protons"], "answer": 1, "why": "Charged particles are directly ionising.", "slides": [{"src": "files/slides/biophys1-radioactivity/19.jpg", "lec": "Radioactivity: general concepts", "n": 19}]}, {"q": "The Bragg peak is:", "options": ["The peak of natural background radiation", "The point where photons are absorbed first", "The maximum energy deposit just before a charged particle stops", "The half-value layer"], "answer": 2, "why": "Protontherapy places it in the tumour to spare healthy tissue.", "slides": [{"src": "files/slides/biophys1-interactions/07.jpg", "lec": "Radiation-matter interactions,", "n": 7}]}, {"q": "α particles are mainly dangerous:", "options": ["Because they travel metres in air", "Because they cross lead", "As external sources through thick walls", "When inhaled or ingested (internal exposure)"], "answer": 3, "why": "They are stopped by paper or the skin surface.", "slides": [{"src": "files/slides/biophys1-interactions/09.jpg", "lec": "Radiation-matter interactions,", "n": 9}]}, {"q": "Bremsstrahlung (braking radiation) is produced when:", "options": ["Neutrons are captured", "A nucleus de-excites", "Electrons are deflected by atomic nuclei", "Positrons annihilate"], "answer": 2, "why": "It is the source of X-rays in the X-ray tube.", "slides": [{"src": "files/slides/biophys1-interactions/11.jpg", "lec": "Radiation-matter interactions,", "n": 11}]}, {"q": "Photon attenuation follows:", "options": ["A quadratic law", "No law", "A linear law", "An exponential law N = N₀·e^(−µx)"], "answer": 3, "why": "Each half-value layer (ln2/µ) halves the beam.", "slides": [{"src": "files/slides/biophys1-interactions/18.jpg", "lec": "Radiation-matter interactions,", "n": 18}]}, {"q": "Absorbed dose is measured in:", "options": ["Gray (J/kg)", "Becquerel", "Coulomb", "Sievert"], "answer": 0, "why": "Equivalent and effective doses are in sievert.", "slides": [{"src": "files/slides/biophys1-radiobiology/05.jpg", "lec": "Radiobiology: biological effects of", "n": 5}]}, {"q": "The radiation weighting factor W_R of α particles is:", "options": ["1", "20", "5", "0.12"], "answer": 1, "why": "Photons and electrons 1, protons 5 (lecture), neutrons 5-20, α 20.", "slides": [{"src": "files/slides/biophys1-radiobiology/07.jpg", "lec": "Radiobiology: biological effects of", "n": 7}]}, {"q": "Effective dose is obtained by:", "options": ["Dividing activity by mass", "Summing equivalent doses weighted by tissue sensitivity (W_T)", "Measuring with a Geiger counter only", "Multiplying absorbed dose by time"], "answer": 1, "why": "E = Σ H_T × W_T.", "slides": [{"src": "files/slides/biophys1-radiobiology/08.jpg", "lec": "Radiobiology: biological effects of", "n": 8}]}, {"q": "The main target of ionising radiation in the body is:", "options": ["Bone mineral", "Water, through radiolysis producing free radicals", "Collagen", "Fat"], "answer": 1, "why": "Water is about 65% of body mass; •OH is a strong oxidant (indirect effect).", "slides": [{"src": "files/slides/biophys1-radiobiology/11.jpg", "lec": "Radiobiology: biological effects of", "n": 11}]}, {"q": "Oxygen in tissues:", "options": ["Has no effect", "Only affects α radiation", "Protects cells from radiation", "Increases radiosensitivity by forming more toxic radical species"], "answer": 3, "why": "This is the oxygen effect; hypoxic tumours are more radioresistant.", "slides": [{"src": "files/slides/biophys1-radiobiology/14.jpg", "lec": "Radiobiology: biological effects of", "n": 14}]}, {"q": "The most lethal DNA lesion caused by radiation is usually:", "options": ["A methylation", "A base mismatch", "A single-strand break", "A double-strand break"], "answer": 3, "why": "Single-strand breaks are easily repaired using the other strand.", "slides": [{"src": "files/slides/biophys1-radiobiology/20.jpg", "lec": "Radiobiology: biological effects of", "n": 20}]}, {"q": "The largest source of exposure for the general population is:", "options": ["Nuclear power plants", "Natural radiation (cosmic, soil, body radionuclides)", "Nuclear test fallout", "Mobile phones"], "answer": 1, "why": "Medical exposure averages about 1 mSv/year.", "slides": [{"src": "files/slides/biophys1-radioprotection/08.jpg", "lec": "Radiation protection and safety in", "n": 8}]}, {"q": "The three rules for reducing external exposure are:", "options": ["Activity, half-life, mass", "Gloves, mask, gown", "Dose, rate, energy", "Time, distance, shielding"], "answer": 3, "why": "Shorter time, greater distance, lead screens and aprons.", "slides": [{"src": "files/slides/biophys1-radioprotection/13.jpg", "lec": "Radiation protection and safety in", "n": 13}]}, {"q": "Internal contamination means:", "options": ["Irradiation by X-rays", "Radioactive dust on clothing", "Exposure from a source outside the body", "Intake of radioactive material by inhalation, ingestion or wounds"], "answer": 3, "why": "External contamination = material deposited on skin, hair or surfaces.", "slides": [{"src": "files/slides/biophys1-radioprotection/22.jpg", "lec": "Radiation protection and safety in", "n": 22}]}, {"q": "The refractive index n of a medium equals:", "options": ["c/v", "v/c", "1/λ", "c × v"], "answer": 0, "why": "Higher n means slower light and stronger bending.", "slides": [{"src": "files/slides/biophys1-optics/10.jpg", "lec": "Geometrical optics applied to vision", "n": 10}]}, {"q": "The total dioptric power of the eye at rest is about:", "options": ["+20 D", "+48 D", "+64 D", "+100 D"], "answer": 2, "why": "The anterior corneal surface alone contributes about +48 D.", "slides": [{"src": "files/slides/biophys1-optics/25.jpg", "lec": "Geometrical optics applied to vision", "n": 25}]}, {"q": "During accommodation for near vision:", "options": ["The ciliary muscle relaxes and the zonule tightens", "The cornea flattens", "The ciliary muscle contracts, the zonular fibres relax and the lens becomes more convex", "The retina moves forward"], "answer": 2, "why": "Power increases to focus near objects.", "slides": [{"src": "files/slides/biophys1-optics/28.jpg", "lec": "Geometrical optics applied to vision", "n": 28}]}, {"q": "Presbyopia is corrected with:", "options": ["Converging lenses for near vision", "Diverging lenses for distance", "No correction is possible", "Cylindrical lenses only"], "answer": 0, "why": "The lens hardens with age and accommodation falls.", "slides": [{"src": "files/slides/biophys1-optics/32.jpg", "lec": "Geometrical optics applied to vision", "n": 32}]}]}, {"id": "y1-chem1-sina-mock", "subject": "chem1", "title": "Sina mock exam: Chemistry", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering the atom, Bohr and quantum models, electron configuration and the periodic table. One answer per question, each with a short explanation.", "questions": [{"q": "The atomic number Z is:", "options": ["The number of protons", "The number of nucleons", "The atomic mass", "The number of neutrons"], "answer": 0, "why": "A = protons + neutrons, so N = A − Z.", "slides": [{"src": "files/slides/chem1-matter/06.jpg", "lec": "Structure of matter: the atom and its", "n": 6}]}, {"q": "A nucleus of ²³₁₁Na contains:", "options": ["11 protons and 12 neutrons", "23 protons", "12 protons and 11 neutrons", "11 protons and 23 neutrons"], "answer": 0, "why": "N = A − Z = 23 − 11 = 12.", "slides": [{"src": "files/slides/chem1-matter/09.jpg", "lec": "Structure of matter: the atom and its", "n": 9}]}, {"q": "Isotopes of an element have:", "options": ["The same number of protons but different numbers of neutrons", "Different numbers of protons", "The same mass number", "Different chemical families"], "answer": 0, "why": "Same Z, different A.", "slides": [{"src": "files/slides/chem1-matter/11.jpg", "lec": "Structure of matter: the atom and its", "n": 11}]}, {"q": "The proton mass is about:", "options": ["1836 times the electron mass", "The same as the electron mass", "Half the neutron mass", "Negligible"], "answer": 0, "why": "The neutron is slightly heavier (1839 mₑ).", "slides": [{"src": "files/slides/chem1-matter/17.jpg", "lec": "Structure of matter: the atom and its", "n": 17}]}, {"q": "1 atomic mass unit (u) is defined as:", "options": ["1/12 of the mass of a carbon-12 atom", "The mass of one proton", "The mass of a hydrogen atom", "1 g/mol"], "answer": 0, "why": "Both scales (u and g/mol) are referenced to ¹²C.", "slides": [{"src": "files/slides/chem1-matter/13.jpg", "lec": "Structure of matter: the atom and its", "n": 13}]}, {"q": "Avogadro's number is approximately:", "options": ["6.02 × 10²³ mol⁻¹", "6.626 × 10⁻³⁴", "1.602 × 10⁻¹⁹", "9.109 × 10⁻³¹"], "answer": 0, "why": "1.602 × 10⁻¹⁹ C is the elementary charge; 6.626 × 10⁻³⁴ J·s is Planck's constant.", "slides": [{"src": "files/slides/chem1-matter/12.jpg", "lec": "Structure of matter: the atom and its", "n": 12}]}, {"q": "Rutherford's model failed because:", "options": ["It had no nucleus", "It ignored protons", "An orbiting electron should radiate energy and spiral into the nucleus, giving a continuous spectrum", "It predicted a discontinuous spectrum"], "answer": 2, "why": "Atoms are stable and hydrogen's spectrum is made of lines.", "slides": [{"src": "files/slides/chem1-bohr/10.jpg", "lec": "Models of the atom: Rutherford,", "n": 10}]}, {"q": "The visible lines of the hydrogen spectrum form the:", "options": ["Lyman series", "Paschen series", "Balmer series", "Brackett series"], "answer": 2, "why": "Lyman lines are ultraviolet (transitions to n = 1); Balmer lines end on n = 2.", "slides": [{"src": "files/slides/chem1-bohr/09.jpg", "lec": "Models of the atom: Rutherford,", "n": 9}]}, {"q": "Planck's relation for a quantum of energy is:", "options": ["E = mc²", "λ = h/mv", "ΔE = hν", "E = ½mv²"], "answer": 2, "why": "Energy is exchanged in packets (quanta).", "slides": [{"src": "files/slides/chem1-bohr/11.jpg", "lec": "Models of the atom: Rutherford,", "n": 11}]}, {"q": "In Bohr's model, an electron:", "options": ["Can occupy any orbit", "Moves only on stationary orbits of quantised energy", "Radiates continuously", "Has no energy"], "answer": 1, "why": "It absorbs or emits hν only when jumping between orbits.", "slides": [{"src": "files/slides/chem1-bohr/13.jpg", "lec": "Models of the atom: Rutherford,", "n": 13}]}, {"q": "When an electron falls from n = 3 to n = 2:", "options": ["It absorbs a photon", "Its energy rises", "It emits a photon", "It leaves the atom"], "answer": 2, "why": "Emission: Ef = Ei − hν.", "slides": [{"src": "files/slides/chem1-quantum/07.jpg", "lec": "Quantum mechanics, quantum numbers", "n": 7}]}, {"q": "Bohr's model applies correctly only to:", "options": ["Noble gases", "All atoms", "Metals", "Hydrogen and hydrogen-like (one-electron) ions"], "answer": 3, "why": "Many-electron atoms need quantum mechanics.", "slides": [{"src": "files/slides/chem1-bohr/18.jpg", "lec": "Models of the atom: Rutherford,", "n": 18}]}, {"q": "De Broglie's relation is:", "options": ["Δx·Δp ≥ h/2π", "E = hν", "PV = nRT", "λ = h/(m·v)"], "answer": 3, "why": "Matter has a wave character.", "slides": [{"src": "files/slides/chem1-quantum/02.jpg", "lec": "Quantum mechanics, quantum numbers", "n": 2}]}, {"q": "Heisenberg's uncertainty principle means:", "options": ["Energy is continuous", "Electrons have fixed orbits", "Position and momentum cannot both be known precisely", "Electrons have no mass"], "answer": 2, "why": "So we speak of the probability of presence (orbitals).", "slides": [{"src": "files/slides/chem1-quantum/03.jpg", "lec": "Quantum mechanics, quantum numbers", "n": 3}]}, {"q": "For n = 2, the possible values of l are:", "options": ["1 and 2", "0 and 1", "0, 1 and 2", "0 only"], "answer": 1, "why": "l goes from 0 to n − 1: 2s and 2p, no 2d.", "slides": [{"src": "files/slides/chem1-quantum/09.jpg", "lec": "Quantum mechanics, quantum numbers", "n": 9}]}, {"q": "A d subshell has:", "options": ["7 orbitals", "1 orbital", "3 orbitals", "5 orbitals"], "answer": 3, "why": "2l + 1 orbitals: s 1, p 3, d 5, f 7.", "slides": [{"src": "files/slides/chem1-quantum/14.jpg", "lec": "Quantum mechanics, quantum numbers", "n": 14}]}, {"q": "The maximum number of electrons in a p subshell is:", "options": ["6", "10", "2", "14"], "answer": 0, "why": "2(2l + 1) = 6.", "slides": [{"src": "files/slides/chem1-configuration/12.jpg", "lec": "Atomic orbitals and electron", "n": 12}]}, {"q": "The Pauli exclusion principle states that:", "options": ["Electrons fill lower energy levels first", "Energy is quantised", "Electrons spread out with parallel spins", "No two electrons in an atom can have the same four quantum numbers"], "answer": 3, "why": "So each orbital holds at most two electrons with opposite spins.", "slides": [{"src": "files/slides/chem1-configuration/18.jpg", "lec": "Atomic orbitals and electron", "n": 18}]}, {"q": "Hund's rule states that:", "options": ["Orbitals fill in order of n + l", "In a subshell, electrons occupy separate orbitals with parallel spins before pairing", "Two electrons cannot share four quantum numbers", "Electrons always pair first"], "answer": 1, "why": "Aufbau gives the order of filling; Pauli limits two per orbital."}, {"q": "Which orbital fills before 3d?", "options": ["4p", "4d", "4s", "5s"], "answer": 2, "why": "n + l: 4s = 4, 3d = 5."}, {"q": "The electron configuration of sodium (Z = 11) is:", "options": ["1s² 2s² 2p⁵ 3s²", "1s² 2s² 2p⁶ 3p¹", "1s² 2s² 2p⁶ 3s¹", "1s² 2s² 2p⁷"], "answer": 2, "why": "One valence electron in 3s: an alkali metal."}, {"q": "The configuration of chromium ends in 3d⁵ 4s¹ because:", "options": ["Half-filled subshells are especially stable", "It has 25 electrons", "It is a noble gas", "Of Hund's rule only"], "answer": 0, "why": "Copper (3d¹⁰ 4s¹) is the other classic exception (filled d subshell).", "slides": [{"src": "files/slides/chem1-configuration/17.jpg", "lec": "Atomic orbitals and electron", "n": 17}]}, {"q": "The modern periodic table orders elements by:", "options": ["Date of discovery", "Atomic number Z", "Density", "Atomic mass"], "answer": 1, "why": "Position reflects the electron configuration.", "slides": [{"src": "files/slides/chem1-periodic/12.jpg", "lec": "The periodic table", "n": 12}]}, {"q": "Elements in the same column (group) have:", "options": ["The same number of shells", "The same mass", "The same outer-shell configuration and similar properties", "The same number of neutrons"], "answer": 2, "why": "Elements in the same row (period) fill the same shell.", "slides": [{"src": "files/slides/chem1-periodic/13.jpg", "lec": "The periodic table", "n": 13}]}, {"q": "Alkali metals (group IA):", "options": ["Are noble gases", "Have an ns¹ configuration and form M⁺ ions", "Have an ns² configuration", "Form basic M²⁺ ions"], "answer": 1, "why": "Alkaline earths (IIA) are ns² and form M²⁺."}]}, {"id": "physio-sina-mock", "subject": "physio", "title": "Sina mock exam: Physiology", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering organisation of the nervous system, neurons, synapses, the myotatic reflex and pain. One answer per question, each with a short explanation.", "questions": [{"q": "CSF is produced mainly by:", "options": ["The dura mater", "The choroid plexus", "The pia mater", "The arachnoid granulations"], "answer": 1, "why": "It is reabsorbed by the arachnoid granulations into the superior sagittal sinus.", "slides": [{"src": "files/slides/physio-intro-neuro/28.jpg", "lec": "Introduction to neurophysiology", "n": 28}]}, {"q": "The correct CSF pathway is:", "options": ["Fourth ventricle → aqueduct → third ventricle → lateral ventricles", "Lateral ventricles → foramen of Monro → third ventricle → cerebral aqueduct → fourth ventricle → subarachnoid space", "Subarachnoid space → choroid plexus → lateral ventricles", "Lateral ventricles → fourth ventricle → third ventricle"], "answer": 1, "why": "It leaves the fourth ventricle through the foramina of Magendie (and Luschka).", "slides": [{"src": "files/slides/physio-pain/35.jpg", "lec": "Physiology of pain", "n": 35}]}, {"q": "Thanks to CSF buoyancy, the brain's effective weight falls from about 1400 g to about:", "options": ["5 g", "50 g", "700 g", "1000 g"], "answer": 1, "why": "Protection and buoyancy are major functions of CSF.", "slides": [{"src": "files/slides/physio-intro-neuro/29.jpg", "lec": "Introduction to neurophysiology", "n": 29}]}, {"q": "Sympathetic stimulation causes:", "options": ["Bradycardia", "Pupil dilation and reduced gut motility", "Increased gut motility", "Pupil constriction and copious saliva"], "answer": 1, "why": "Parasympathetic: miosis, copious saliva, more gut motility.", "slides": [{"src": "files/slides/physio-intro-neuro/31.jpg", "lec": "Introduction to neurophysiology", "n": 31}]}, {"q": "The resting membrane potential of a typical neuron is about:", "options": ["-90 mV in all cells", "+30 mV", "0 mV", "-70 mV"], "answer": 3, "why": "Action potentials overshoot to about +30 mV.", "slides": [{"src": "files/slides/physio-neurons/71.jpg", "lec": "Neurons and electrical communication", "n": 71}]}, {"q": "The depolarisation phase of the action potential is due to:", "options": ["K⁺ efflux", "Ca²⁺ efflux", "Cl⁻ influx", "Na⁺ influx through voltage-gated channels"], "answer": 3, "why": "Repolarisation = K⁺ efflux; Na⁺ channels then inactivate.", "slides": [{"src": "files/slides/physio-neurons/77.jpg", "lec": "Neurons and electrical communication", "n": 77}]}, {"q": "Action potentials are normally initiated at:", "options": ["The nucleus", "The axon terminals", "The axon hillock (trigger zone)", "The dendrites"], "answer": 2, "why": "It has the highest density of voltage-gated Na⁺ channels.", "slides": [{"src": "files/slides/physio-neurons/89.jpg", "lec": "Neurons and electrical communication", "n": 89}]}, {"q": "Inactivation of voltage-gated Na⁺ channels explains:", "options": ["The resting potential", "The absolute refractory period", "Graded potentials", "Temporal summation"], "answer": 1, "why": "A new action potential cannot fire until the channels recover.", "slides": [{"src": "files/slides/physio-neurons/73.jpg", "lec": "Neurons and electrical communication", "n": 73}]}, {"q": "Graded potentials:", "options": ["Are all-or-none", "Vary in size with the stimulus and fade with distance", "Only occur in muscle", "Travel without decrement along the axon"], "answer": 1, "why": "Action potentials are all-or-none and conducted without decrement.", "slides": [{"src": "files/slides/physio-neurons/57.jpg", "lec": "Neurons and electrical communication", "n": 57}]}, {"q": "Neurons cannot divide because they lack:", "options": ["A centrosome", "Mitochondria", "Nissl bodies", "A nucleus"], "answer": 0, "why": "Every neuron has exactly one axon.", "slides": [{"src": "files/slides/physio-neurons/21.jpg", "lec": "Neurons and electrical communication", "n": 21}]}, {"q": "Myelin in the CNS is made by:", "options": ["Schwann cells", "Astrocytes", "Microglia", "Oligodendrocytes"], "answer": 3, "why": "Schwann cells myelinate peripheral axons.", "slides": [{"src": "files/slides/physio-neurons/81.jpg", "lec": "Neurons and electrical communication", "n": 81}]}, {"q": "Neurotransmitter release at the axon terminal is triggered by:", "options": ["Na⁺ entry alone", "Ca²⁺ entry through voltage-gated Ca²⁺ channels", "Cl⁻ entry", "K⁺ exit"], "answer": 1, "why": "Ca²⁺ triggers vesicle fusion (exocytosis).", "slides": [{"src": "files/slides/physio-chemical/18.jpg", "lec": "Synapses and chemical communication", "n": 18}]}, {"q": "The main excitatory neurotransmitter of the CNS is:", "options": ["Glycine", "GABA", "Glutamate", "Dopamine"], "answer": 2, "why": "GABA (brain) and glycine (spinal cord) are the main inhibitory ones.", "slides": [{"src": "files/slides/physio-chemical/29.jpg", "lec": "Synapses and chemical communication", "n": 29}]}, {"q": "Spatial summation means:", "options": ["Inhibition by the cortex", "One synapse firing rapidly", "Inputs from several synapses arriving at the same time add up", "Signals travelling back up the axon"], "answer": 2, "why": "Temporal summation = repeated firing of one synapse.", "slides": [{"src": "files/slides/physio-chemical/26.jpg", "lec": "Synapses and chemical communication", "n": 26}]}, {"q": "Compared with chemical synapses, electrical synapses:", "options": ["Need neurotransmitters", "Pass current directly through gap junctions, quickly and often in both directions", "Are slower", "Cannot synchronise cells"], "answer": 1, "why": "Chemical synapses are one-way and slower but can amplify and be modulated."}, {"q": "The myotatic (stretch) reflex is:", "options": ["Started by Golgi tendon organs", "Monosynaptic: Ia afferent to alpha motor neuron", "Polysynaptic", "Controlled by the cortex"], "answer": 1, "why": "The muscle spindle senses stretch.", "slides": [{"src": "files/slides/physio-myotatic/47.jpg", "lec": "The myotatic reflexes", "n": 47}]}, {"q": "The receptor of the stretch reflex is:", "options": ["A free nerve ending", "The Golgi tendon organ", "The muscle spindle", "The Pacinian corpuscle"], "answer": 2, "why": "Golgi tendon organs sense tension (Ib fibres) and cause the inverse myotatic reflex.", "slides": [{"src": "files/slides/physio-myotatic/39.jpg", "lec": "The myotatic reflexes", "n": 39}]}, {"q": "During the stretch reflex, the antagonist muscle:", "options": ["Is not affected", "Relaxes (reciprocal inhibition)", "Is stretched further", "Contracts"], "answer": 1, "why": "An inhibitory interneuron inhibits the antagonist.", "slides": [{"src": "files/slides/physio-myotatic/48.jpg", "lec": "The myotatic reflexes", "n": 48}]}, {"q": "Brisk (exaggerated) tendon reflexes suggest:", "options": ["An upper motor neuron lesion above the arc", "A peripheral neuropathy", "A lesion of the reflex arc", "Muscle disease"], "answer": 0, "why": "Weak or absent reflexes point to the arc itself.", "slides": [{"src": "files/slides/physio-myotatic/17.jpg", "lec": "The myotatic reflexes", "n": 17}]}, {"q": "Gamma motor neurons:", "options": ["Form the Ia afferent", "Carry pain", "Supply intrafusal fibres and keep the spindle sensitive", "Supply extrafusal fibres"], "answer": 2, "why": "Alpha-gamma coactivation keeps the spindle taut during contraction.", "slides": [{"src": "files/slides/physio-myotatic/49.jpg", "lec": "The myotatic reflexes", "n": 49}]}, {"q": "Fast pain is carried by:", "options": ["A-alpha fibres", "C fibres", "B fibres", "A-delta fibres"], "answer": 3, "why": "A-delta: sharp, well localised; C fibres: slow, burning pain."}, {"q": "Allodynia is:", "options": ["Pain from a normally harmless stimulus", "Absence of pain", "An exaggerated response to a painful stimulus", "Unconscious nociception"], "answer": 0, "why": "Hyperalgesia = exaggerated response to a noxious stimulus.", "slides": [{"src": "files/slides/physio-pain/04.jpg", "lec": "Physiology of pain", "n": 4}]}, {"q": "Pain receptors (nociceptors) are:", "options": ["Free nerve endings that adapt very little", "Photoreceptors", "Encapsulated endings that adapt fast", "Muscle spindles"], "answer": 0, "why": "Little adaptation keeps the warning going.", "slides": [{"src": "files/slides/physio-pain/10.jpg", "lec": "Physiology of pain", "n": 10}]}, {"q": "Which substance sensitises nociceptors without exciting them directly?", "options": ["Bradykinin", "Prostaglandins", "Histamine", "K⁺"], "answer": 1, "why": "Prostaglandins and substance P sensitise; NSAIDs block prostaglandin synthesis.", "slides": [{"src": "files/slides/physio-pain/14.jpg", "lec": "Physiology of pain", "n": 14}]}, {"q": "The gate control theory states that pain transmission in the dorsal horn can be reduced by:", "options": ["Cutting the spinal cord", "Blocking glutamate in the muscle", "Activity in large Aβ touch fibres", "More C-fibre activity"], "answer": 2, "why": "Rubbing a painful area activates inhibitory interneurons.", "slides": [{"src": "files/slides/physio-pain/51.jpg", "lec": "Physiology of pain", "n": 51}]}]}, {"id": "semio-sina-mock", "subject": "semio", "title": "Sina mock exam: Semiology", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering respiratory symptoms, examination and syndromes, cardiovascular examination and left heart failure. One answer per question, each with a short explanation.", "questions": [{"q": "A cough lasting 5 weeks is:", "options": ["Chronic", "Subacute", "Recurrent", "Acute"], "answer": 1, "why": "Acute under 3 weeks, subacute 3-8 weeks, chronic over 8 weeks.", "slides": [{"src": "files/slides/semio-resp-symptoms/07.jpg", "lec": "Respiratory clinical symptoms", "n": 7}]}, {"q": "Chronic bronchitis is defined as:", "options": ["Dry cough for 1 month", "Productive morning cough at least 3 months a year for 2 consecutive years", "Wheeze at night", "Haemoptysis twice a year"], "answer": 1, "why": "Classic clinical definition.", "slides": [{"src": "files/slides/semio-resp-symptoms/15.jpg", "lec": "Respiratory clinical symptoms", "n": 15}]}, {"q": "A dry chronic cough can be caused by:", "options": ["β-blockers", "Diuretics", "ACE inhibitors", "Antibiotics"], "answer": 2, "why": "Also GERD, asthma, rhinosinusitis, interstitial disease and cancer.", "slides": [{"src": "files/slides/semio-resp-symptoms/17.jpg", "lec": "Respiratory clinical symptoms", "n": 17}]}, {"q": "A bitonal cough suggests:", "options": ["Compression of the recurrent laryngeal nerve", "Pleural effusion", "Asthma", "Bronchiectasis"], "answer": 0, "why": "Vocal cord palsy gives a two-tone cough.", "slides": [{"src": "files/slides/semio-resp-symptoms/12.jpg", "lec": "Respiratory clinical symptoms", "n": 12}]}, {"q": "Pink frothy sputum suggests:", "options": ["Anaerobic infection", "Asthma", "Acute pulmonary oedema", "Bronchiectasis"], "answer": 2, "why": "Foul smell suggests anaerobes; pearly sputum suggests asthma.", "slides": [{"src": "files/slides/semio-resp-symptoms/27.jpg", "lec": "Respiratory clinical symptoms", "n": 27}]}, {"q": "Bronchorrhoea is sputum production of more than:", "options": ["1 L/day", "30 mL/day", "10 mL/day", "100 mL/day"], "answer": 3, "why": "Over 30 mL/day is excessive; over 100 mL/day is bronchorrhoea.", "slides": [{"src": "files/slides/semio-resp-symptoms/25.jpg", "lec": "Respiratory clinical symptoms", "n": 25}]}, {"q": "A vomica of clear 'rock-water' fluid suggests:", "options": ["Amoebic abscess", "Tuberculosis", "A ruptured hydatid cyst", "Liver abscess fistula"], "answer": 2, "why": "Chocolate-coloured = amoebic abscess; pus with bile = liver abscess fistula.", "slides": [{"src": "files/slides/semio-resp-syndromes/51.jpg", "lec": "Thoracic syndromes", "n": 51}]}, {"q": "Haemoptysis:", "options": ["Comes from the digestive tract", "Is only an emergency if more than 500 mL", "Is dark and mixed with food", "Is always an emergency, whatever the amount"], "answer": 3, "why": "Blood coughed up from the lower airways.", "slides": [{"src": "files/slides/semio-resp-symptoms/40.jpg", "lec": "Respiratory clinical symptoms", "n": 40}]}, {"q": "Compared with haematemesis, haemoptysis is usually:", "options": ["Bright red, frothy, coughed up", "Acid", "Followed by melaena only", "Dark, with food debris, after vomiting"], "answer": 0, "why": "Haematemesis is vomited, dark, with food, often followed by melaena.", "slides": [{"src": "files/slides/semio-resp-symptoms/39.jpg", "lec": "Respiratory clinical symptoms", "n": 39}]}, {"q": "The normal respiratory rate in adults is:", "options": ["20-30/min", "12-20/min", "30-40/min", "6-10/min"], "answer": 1, "why": "Over 20 = polypnoea; under 12 = bradypnoea.", "slides": [{"src": "files/slides/semio-resp-exam/12.jpg", "lec": "Respiratory clinical examination", "n": 12}]}, {"q": "A barrel chest is typical of:", "options": ["Pneumothorax", "Emphysema", "Pleural effusion", "Pneumonia"], "answer": 1, "why": "Increased anteroposterior diameter from hyperinflation.", "slides": [{"src": "files/slides/semio-resp-exam/07.jpg", "lec": "Respiratory clinical examination", "n": 7}]}, {"q": "Horner's syndrome combines:", "options": ["Miosis, ptosis, anhidrosis", "Clubbing and cyanosis", "Mydriasis, ptosis, sweating", "Exophthalmos and diplopia"], "answer": 0, "why": "It can reveal an apical (Pancoast) tumour.", "slides": [{"src": "files/slides/semio-resp-syndromes/71.jpg", "lec": "Thoracic syndromes", "n": 71}]}, {"q": "Tactile fremitus is increased in:", "options": ["Pleural effusion", "Pneumothorax", "Emphysema", "Pneumonia (consolidation)"], "answer": 3, "why": "Solid lung transmits vibrations better; air or fluid in the pleura damps them.", "slides": [{"src": "files/slides/semio-resp-syndromes/39.jpg", "lec": "Thoracic syndromes", "n": 39}]}, {"q": "Hyperresonance on percussion suggests:", "options": ["Pneumothorax or emphysema", "Atelectasis", "Consolidation", "Pleural effusion"], "answer": 0, "why": "Dullness suggests fluid or consolidation.", "slides": [{"src": "files/slides/semio-resp-exam/35.jpg", "lec": "Respiratory clinical examination", "n": 35}]}, {"q": "Fine 'Velcro' crackles are typical of:", "options": ["Upper airway obstruction", "Asthma only", "Pulmonary fibrosis (also fluid, infection)", "Normal lungs"], "answer": 2, "why": "Coarse crackles suggest secretions; wheeze suggests narrowed airways.", "slides": [{"src": "files/slides/semio-resp-exam/40.jpg", "lec": "Respiratory clinical examination", "n": 40}]}, {"q": "Stridor is:", "options": ["Normal tracheal breathing", "A pleural rub", "An expiratory wheeze from small airways", "A loud inspiratory sound from upper airway obstruction"], "answer": 3, "why": "It is an emergency sign.", "slides": [{"src": "files/slides/semio-resp-exam/41.jpg", "lec": "Respiratory clinical examination", "n": 41}]}, {"q": "A pleural rub sounds like:", "options": ["Whistling", "Velcro", "Walking on fresh snow", "Rice crispies"], "answer": 2, "why": "It disappears when the effusion grows and separates the layers.", "slides": [{"src": "files/slides/semio-resp-exam/41.jpg", "lec": "Respiratory clinical examination", "n": 41}]}, {"q": "Pleural effusion gives:", "options": ["Normal findings", "Dullness and increased fremitus", "Hyperresonance and increased fremitus", "Dullness and decreased fremitus"], "answer": 3, "why": "X-ray: meniscus opacity, blunted costophrenic angle.", "slides": [{"src": "files/slides/semio-resp-syndromes/46.jpg", "lec": "Thoracic syndromes", "n": 46}]}, {"q": "A large pleural effusion pushes the trachea:", "options": ["Away from the effusion", "Downwards", "It never moves", "Towards the effusion"], "answer": 0, "why": "Atelectasis (collapse) pulls it towards the lesion.", "slides": [{"src": "files/slides/semio-resp-syndromes/06.jpg", "lec": "Thoracic syndromes", "n": 6}]}, {"q": "Thoracentesis is performed:", "options": ["Through the sternum", "In the second intercostal space anteriorly always", "Below the rib, lying flat", "Sitting, in the zone of dullness, above the upper border of the lower rib"], "answer": 3, "why": "Above the rib avoids the intercostal neurovascular bundle.", "slides": [{"src": "files/slides/semio-resp-syndromes/12.jpg", "lec": "Thoracic syndromes", "n": 12}]}, {"q": "A pleural fluid with albumin above 30 g/L is:", "options": ["Chylothorax by definition", "A transudate", "Normal", "An exudate"], "answer": 3, "why": "Exudate = inflammatory; transudate = mechanical (heart failure, cirrhosis).", "slides": [{"src": "files/slides/semio-resp-syndromes/16.jpg", "lec": "Thoracic syndromes", "n": 16}]}, {"q": "Consolidation on X-ray typically shows:", "options": ["An alveolar opacity with an air bronchogram", "Lucency without lung markings", "A meniscus", "A visceral pleural line"], "answer": 0, "why": "Pneumothorax: lucency without markings and a visible pleural line.", "slides": [{"src": "files/slides/semio-resp-syndromes/39.jpg", "lec": "Thoracic syndromes", "n": 39}]}, {"q": "Osler nodes and Janeway lesions suggest:", "options": ["Pulmonary embolism", "Hypercholesterolaemia", "Infective endocarditis", "Marfan syndrome"], "answer": 2, "why": "Osler nodes are painful, Janeway lesions painless; xanthelasma suggests hypercholesterolaemia.", "slides": [{"src": "files/slides/semio-cv-intro/09.jpg", "lec": "Cardiovascular semiology: introduction", "n": 9}]}, {"q": "Jugular venous distension above 4 cm (from the sternal angle) suggests:", "options": ["Left heart failure only", "Raised CVP / right heart failure", "Normal finding", "Dehydration"], "answer": 1, "why": "Examined at 15-45° with the head turned left.", "slides": [{"src": "files/slides/semio-cv-intro/16.jpg", "lec": "Cardiovascular semiology: introduction", "n": 16}]}, {"q": "Systolic heart failure is characterised by:", "options": ["A stiff, thick ventricle that cannot fill", "An ejection fraction of 40% or less", "A normal ejection fraction", "High stroke volume"], "answer": 1, "why": "Diastolic failure: stiff ventricle, normal EF.", "slides": [{"src": "files/slides/semio-cv-lhf/12.jpg", "lec": "Left heart failure", "n": 12}]}]}, {"id": "biochem-sina-mock", "subject": "biochem", "title": "Sina mock exam: Clinical Biochemistry", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering the preanalytical phase, thyroid, adrenal medulla, insulin and steroid hormones (the midterm lectures). One answer per question, each with a short explanation.", "questions": [{"q": "Most laboratory errors occur in:", "options": ["The analytical phase", "The postanalytical phase", "Result transmission only", "The preanalytical phase"], "answer": 3, "why": "About 68% of errors happen before the sample reaches the analyser.", "slides": [{"src": "files/slides/biochem-preanalytical/16.jpg", "lec": "Preanalytical phase of biochemical", "n": 16}]}, {"q": "Before blood sampling, the patient should have fasted for at least:", "options": ["2 hours", "24 hours", "8 hours, sampled between 7 and 9 a.m.", "No fasting is needed"], "answer": 2, "why": "Without fasting, lipids can be about 21% higher.", "slides": [{"src": "files/slides/biochem-preanalytical/34.jpg", "lec": "Preanalytical phase of biochemical", "n": 34}]}, {"q": "After intense exercise, the analyte that can quadruple is:", "options": ["Glucose", "Creatine kinase (CK)", "Sodium", "TSH"], "answer": 1, "why": "12 hours of rest are advised before sampling.", "slides": [{"src": "files/slides/biochem-preanalytical/33.jpg", "lec": "Preanalytical phase of biochemical", "n": 33}]}, {"q": "The tourniquet should be released within:", "options": ["1 minute", "5 minutes", "10 minutes", "10 seconds"], "answer": 0, "why": "Longer application gives up to 10% error (haemoconcentration).", "slides": [{"src": "files/slides/biochem-preanalytical/41.jpg", "lec": "Preanalytical phase of biochemical", "n": 41}]}, {"q": "Haemolysis of a sample falsely raises:", "options": ["Glucose", "Potassium and intracellular enzymes", "Albumin", "Sodium"], "answer": 1, "why": "Red cells release K⁺, LDH and AST.", "slides": [{"src": "files/slides/biochem-preanalytical/59.jpg", "lec": "Preanalytical phase of biochemical", "n": 59}]}, {"q": "If a sample waits too long before analysis:", "options": ["Bilirubin rises", "Glucose rises", "All values stay stable", "Glucose falls while potassium and transaminases rise"], "answer": 3, "why": "Analyse within 2 hours; protect bilirubin samples from light.", "slides": [{"src": "files/slides/biochem-preanalytical/55.jpg", "lec": "Preanalytical phase of biochemical", "n": 55}]}, {"q": "During pregnancy, serum ALP is:", "options": ["Unchanged", "Decreased", "Increased (placental ALP)", "Undetectable"], "answer": 2, "why": "Proteins, iron and ferritin fall by haemodilution; ALP is also higher in children (bone growth).", "slides": [{"src": "files/slides/biochem-steroids/39.jpg", "lec": "Steroid hormones", "n": 39}]}, {"q": "The enzyme that oxidises iodide and couples iodotyrosines in the thyroid is:", "options": ["Aromatase", "Deiodinase", "Thyroid peroxidase (TPO)", "Tyrosine hydroxylase"], "answer": 2, "why": "TPO oxidises iodide, iodinates tyrosines and couples MIT/DIT.", "slides": [{"src": "files/slides/biochem-thyroid/09.jpg", "lec": "Thyroid hormones", "n": 9}]}, {"q": "T4 is formed by coupling:", "options": ["MIT + MIT", "Two thyronines", "MIT + DIT", "DIT + DIT"], "answer": 3, "why": "DIT + MIT = T3.", "slides": [{"src": "files/slides/biochem-thyroid/10.jpg", "lec": "Thyroid hormones", "n": 10}]}, {"q": "Thyroglobulin is stored in:", "options": ["The parathyroid", "The colloid of the thyroid follicle", "The blood", "The pituitary"], "answer": 1, "why": "Follicles have a single layer of cubic cells around the colloid.", "slides": [{"src": "files/slides/biochem-thyroid/04.jpg", "lec": "Thyroid hormones", "n": 4}]}, {"q": "The main plasma carrier of thyroid hormones is:", "options": ["SHBG", "Transferrin", "Thyroxine-binding globulin (TBG)", "Albumin only"], "answer": 2, "why": "Only the free fraction is active.", "slides": [{"src": "files/slides/biochem-thyroid/14.jpg", "lec": "Thyroid hormones", "n": 14}]}, {"q": "The most active thyroid hormone in tissues is:", "options": ["T4", "Reverse T3", "T3, formed from T4 by deiodination", "Thyroglobulin"], "answer": 2, "why": "Reverse T3 is inactive.", "slides": [{"src": "files/slides/biochem-thyroid/12.jpg", "lec": "Thyroid hormones", "n": 12}]}, {"q": "In primary hypothyroidism, TSH is:", "options": ["Undetectable", "High", "Normal", "Low"], "answer": 1, "why": "Low free T4 removes negative feedback, so TSH rises."}, {"q": "The rate-limiting enzyme of catecholamine synthesis is:", "options": ["COMT", "Tyrosine hydroxylase", "DOPA decarboxylase", "PNMT"], "answer": 1, "why": "It is the feedback step.", "slides": [{"src": "files/slides/biochem-adrenal-medulla/07.jpg", "lec": "Adrenal medulla hormones", "n": 7}]}, {"q": "PNMT converts:", "options": ["Adrenaline to metanephrine", "Dopamine to noradrenaline", "Tyrosine to DOPA", "Noradrenaline to adrenaline"], "answer": 3, "why": "PNMT is induced by cortisol, which is why the medulla makes mostly adrenaline.", "slides": [{"src": "files/slides/biochem-adrenal-medulla/05.jpg", "lec": "Adrenal medulla hormones", "n": 5}]}, {"q": "The first-line test for pheochromocytoma is:", "options": ["Urine glucose", "Serum cortisol", "Plasma (free) metanephrines", "24-h urinary dopamine"], "answer": 2, "why": "Urinary dopamine and VMA are used for neuroblastoma."}, {"q": "The main urinary catecholamine metabolite (about 80%) is:", "options": ["Free adrenaline", "Dopamine", "Metanephrine", "Vanillylmandelic acid (VMA)"], "answer": 3, "why": "Metanephrines 10-15%, free catecholamines about 5%.", "slides": [{"src": "files/slides/biochem-adrenal-medulla/15.jpg", "lec": "Adrenal medulla hormones", "n": 15}]}, {"q": "Insulin is made of:", "options": ["An A chain (21 aa) and a B chain (30 aa) joined by disulphide bridges", "Three chains", "Two identical chains", "One chain of 51 amino acids"], "answer": 0, "why": "Proinsulin is cleaved into insulin + C-peptide.", "slides": [{"src": "files/slides/biochem-insulin/05.jpg", "lec": "Insulin", "n": 5}]}, {"q": "C-peptide is useful because it:", "options": ["Lowers glucose", "Is a marker of thyroid function", "Reflects endogenous insulin secretion", "Raises blood pressure"], "answer": 2, "why": "It is released in equal amounts with insulin and is absent from injected insulin."}, {"q": "Glucose triggers insulin secretion by the sequence:", "options": ["ATP rises → K⁺(ATP) channels close → depolarisation → Ca²⁺ entry → exocytosis", "ATP falls → K⁺ channels open", "cAMP falls → Na⁺ entry", "Ca²⁺ exits the cell"], "answer": 0, "why": "Sulfonylureas also close K⁺(ATP) channels.", "slides": [{"src": "files/slides/biochem-insulin/08.jpg", "lec": "Insulin", "n": 8}]}, {"q": "Insulin inhibits:", "options": ["Glucose uptake by muscle", "Glycogenesis", "Lipolysis and gluconeogenesis", "Triglyceride synthesis"], "answer": 2, "why": "It is the only glucose-lowering hormone and promotes storage.", "slides": [{"src": "files/slides/biochem-insulin/11.jpg", "lec": "Insulin", "n": 11}]}, {"q": "HbA1c reflects mean blood glucose over about:", "options": ["1 year", "15 days", "1 week", "2-3 months"], "answer": 3, "why": "Fructosamine reflects about 2-3 weeks and is used when haemoglobinopathy distorts HbA1c.", "slides": [{"src": "files/slides/biochem-insulin/14.jpg", "lec": "Insulin", "n": 14}]}, {"q": "The key (rate-limiting) step of steroid synthesis, cholesterol → pregnenolone, is catalysed by:", "options": ["Aromatase", "11β-hydroxylase", "21-hydroxylase", "20-22 desmolase (side-chain cleavage)"], "answer": 3, "why": "It happens in mitochondria and is stimulated by ACTH, LH and FSH.", "slides": [{"src": "files/slides/biochem-steroids/19.jpg", "lec": "Steroid hormones", "n": 19}]}, {"q": "Aldosterone is made in:", "options": ["The reticularis", "The fasciculata", "The glomerulosa", "The medulla"], "answer": 2, "why": "Fasciculata = cortisol; reticularis = androgens (DHEA).", "slides": [{"src": "files/slides/biochem-steroids/06.jpg", "lec": "Steroid hormones", "n": 6}]}, {"q": "In 21-hydroxylase deficiency:", "options": ["Only aldosterone rises", "Oestrogens fall only", "Cortisol rises and ACTH falls", "17-OH progesterone and androgens rise, cortisol and aldosterone fall, ACTH rises"], "answer": 3, "why": "Ambiguous genitalia in girls and salt loss.", "slides": [{"src": "files/slides/biochem-steroids/63.jpg", "lec": "Steroid hormones", "n": 63}]}]}, {"id": "firstaid-sina-mock", "subject": "firstaid", "title": "Sina mock exam: First Aid", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering protection and alert, cardiac arrest, bleeding, trauma and intracranial pressure. One answer per question, each with a short explanation.", "questions": [{"q": "The three aims of first aid are:", "options": ["Call, wait, record", "Diagnose, treat, discharge", "Preserve life, prevent worsening, promote recovery", "Transport, operate, rehabilitate"], "answer": 2, "why": "Care given before professional help arrives.", "slides": [{"src": "files/slides/fa-trauma-burns/03.jpg", "lec": "Trauma injuries and burns", "n": 3}]}, {"q": "Before approaching a victim, the first responder must:", "options": ["Move the victim quickly", "Give water", "Start CPR immediately", "Secure the scene and ensure their own safety"], "answer": 3, "why": "Self-control and safety come first; use PPE against body fluids.", "slides": [{"src": "files/slides/fa-protection/12.jpg", "lec": "Protection and alert", "n": 12}]}, {"q": "At a road accident you should NOT:", "options": ["Use the hand brake and block the wheels", "Switch off the ignitions", "Try to right a vehicle lying on its side", "Call the EMS"], "answer": 2, "why": "Stabilise it only if safe and trained.", "slides": [{"src": "files/slides/fa-protection/12.jpg", "lec": "Protection and alert", "n": 12}]}, {"q": "The 'three Cs' are:", "options": ["Count, Check, Carry", "Calm, Cool, Collected", "Compress, Clear, Cover", "Check, Call, Care"], "answer": 3, "why": "Once the scene is safe.", "slides": [{"src": "files/slides/fa-protection/13.jpg", "lec": "Protection and alert", "n": 13}]}, {"q": "In the primary survey ABCDE, 'D' stands for:", "options": ["Diagnosis", "Disability (neurological status)", "Dressing", "Defibrillation"], "answer": 1, "why": "Airway, Breathing, Circulation, Disability, Exposure/Environment.", "slides": [{"src": "files/slides/fa-trauma-burns/04.jpg", "lec": "Trauma injuries and burns", "n": 4}]}, {"q": "The Moroccan emergency (SAMU) number taught in the course is:", "options": ["15", "19", "177", "112"], "answer": 0, "why": "Give an exact location when calling.", "slides": [{"src": "files/slides/fa-cardiac-arrest/09.jpg", "lec": "Cardiac arrest", "n": 9}]}, {"q": "Sudden cardiac arrest is most often due to:", "options": ["Ventricular fibrillation or pulseless ventricular tachycardia", "Asystole", "Atrial fibrillation", "Bradycardia"], "answer": 0, "why": "These shockable rhythms are why early defibrillation matters.", "slides": [{"src": "files/slides/fa-cardiac-arrest/02.jpg", "lec": "Cardiac arrest", "n": 2}]}, {"q": "In a young athlete, sudden cardiac death is classically due to:", "options": ["Valve calcification", "Hypertrophic cardiomyopathy or anomalous coronary origin", "Coronary atherosclerosis", "Pulmonary embolism only"], "answer": 1, "why": "Coronary disease dominates in older people.", "slides": [{"src": "files/slides/fa-cardiac-arrest/06.jpg", "lec": "Cardiac arrest", "n": 6}]}, {"q": "Agonal gasping in an unresponsive person should be considered:", "options": ["A sign of cardiac arrest", "A seizure that needs no CPR", "Sleep", "Normal breathing"], "answer": 0, "why": "Start CPR if unresponsive with absent or abnormal breathing.", "slides": [{"src": "files/slides/fa-cardiac-arrest/13.jpg", "lec": "Cardiac arrest", "n": 13}]}, {"q": "Health professionals should check for a pulse for no more than:", "options": ["1 minute", "5 seconds", "10 seconds", "30 seconds"], "answer": 2, "why": "In doubt, start CPR.", "slides": [{"src": "files/slides/fa-cardiac-arrest/12.jpg", "lec": "Cardiac arrest", "n": 12}]}, {"q": "Adult chest compressions should be:", "options": ["5-6 cm deep at 100-120/min, with full recoil", "On the upper sternum", "8 cm deep at 150/min", "2-3 cm deep at 60/min"], "answer": 0, "why": "Lower half of the sternum, minimal interruptions, firm surface.", "slides": [{"src": "files/slides/fa-cardiac-arrest/14.jpg", "lec": "Cardiac arrest", "n": 14}]}, {"q": "The compression-to-ventilation ratio for adult CPR is:", "options": ["15:2", "5:1", "30:2", "30:1"], "answer": 2, "why": "Untrained or unwilling rescuers can give continuous compressions.", "slides": [{"src": "files/slides/fa-cardiac-arrest/22.jpg", "lec": "Cardiac arrest", "n": 22}]}, {"q": "The AED should be attached:", "options": ["Only by a doctor", "As soon as it is available", "After 10 minutes of CPR", "Only after a pulse check of 1 minute"], "answer": 1, "why": "Early defibrillation is a key link in the chain of survival.", "slides": [{"src": "files/slides/fa-cardiac-arrest/10.jpg", "lec": "Cardiac arrest", "n": 10}]}, {"q": "The first step to control external bleeding is:", "options": ["Direct pressure", "Cold water", "Elevation only", "A tourniquet"], "answer": 0, "why": "Then wound packing, then a tourniquet for massive limb bleeding.", "slides": [{"src": "files/slides/fa-bleeding/12.jpg", "lec": "Bleeding", "n": 12}]}, {"q": "A tourniquet is indicated for:", "options": ["Massive, life-threatening limb bleeding when direct pressure fails", "Nosebleeds", "Any bleeding", "Bleeding from the chest"], "answer": 0, "why": "Wide, flat band (7.5-10 cm), never wire or rope; note the time.", "slides": [{"src": "files/slides/fa-bleeding/08.jpg", "lec": "Bleeding", "n": 8}]}, {"q": "A tourniquet should be placed:", "options": ["As close above the wound as possible", "On the neck", "Over a joint", "Below the wound"], "answer": 0, "why": "Twist until bleeding stops.", "slides": [{"src": "files/slides/fa-bleeding/11.jpg", "lec": "Bleeding", "n": 11}]}, {"q": "Shock may develop when blood loss exceeds about:", "options": ["5% of blood volume", "25% of blood volume", "1% of blood volume", "60% before any sign"], "answer": 1, "why": "Check for hidden bleeding, including under the patient.", "slides": [{"src": "files/slides/fa-bleeding/04.jpg", "lec": "Bleeding", "n": 4}]}, {"q": "A pelvic sling should be centred on:", "options": ["The umbilicus", "The knees", "The iliac crests", "The greater trochanters"], "answer": 3, "why": "Remove belts and pocket items first.", "slides": [{"src": "files/slides/fa-bleeding/16.jpg", "lec": "Bleeding", "n": 16}]}, {"q": "In trauma, the airway is managed with:", "options": ["Cervical spine stabilisation", "Head tilt and full neck flexion", "Turning the head sideways", "A pillow under the head"], "answer": 0, "why": "ABCDE with cervical spine protection.", "slides": [{"src": "files/slides/fa-trauma-burns/04.jpg", "lec": "Trauma injuries and burns", "n": 4}]}, {"q": "A palpable radial pulse suggests a systolic pressure of at least about:", "options": ["80 mmHg", "160 mmHg", "40 mmHg", "120 mmHg"], "answer": 0, "why": "Femoral about 70, carotid about 60 mmHg.", "slides": [{"src": "files/slides/fa-trauma-burns/05.jpg", "lec": "Trauma injuries and burns", "n": 5}]}, {"q": "When splinting a fracture you should:", "options": ["Immobilise the joint above and below and check neurovascular status before and after", "Remove all dressings", "Straighten an open fracture by force", "Immobilise only the fracture site"], "answer": 0, "why": "Cover open wounds with dry sterile dressings.", "slides": [{"src": "files/slides/fa-trauma-burns/15.jpg", "lec": "Trauma injuries and burns", "n": 15}]}, {"q": "Removing a motorcycle helmet is absolutely contraindicated if:", "options": ["There is neck pain or paraesthesia during removal, or an impaled object", "The victim is cold", "The helmet is full-face", "The victim is conscious"], "answer": 0, "why": "Otherwise it should be removed pre-hospital for airway care.", "slides": [{"src": "files/slides/fa-trauma-burns/20.jpg", "lec": "Trauma injuries and burns", "n": 20}]}, {"q": "Normal adult intracranial pressure is:", "options": ["20-30 mmHg", "5-15 mmHg", "0-2 mmHg", "40-50 mmHg"], "answer": 1, "why": "Raised ICP is 20 mmHg or more.", "slides": [{"src": "files/slides/fa-neural/11.jpg", "lec": "Neural function: intracranial pressure", "n": 11}]}, {"q": "Cerebral perfusion pressure equals:", "options": ["ICP − MAP", "Systolic − diastolic pressure", "MAP + ICP", "MAP − ICP"], "answer": 3, "why": "Autoregulation keeps flow stable for CPP of about 60-160 mmHg.", "slides": [{"src": "files/slides/fa-neural/17.jpg", "lec": "Neural function: intracranial pressure", "n": 17}]}, {"q": "The Monro-Kellie doctrine states that:", "options": ["The skull can expand", "In a fixed skull, an increase in brain, blood or CSF volume raises ICP unless another decreases", "CSF cannot move", "ICP depends only on blood pressure"], "answer": 1, "why": "Every ICP treatment works by reducing one of the three volumes.", "slides": [{"src": "files/slides/fa-neural/14.jpg", "lec": "Neural function: intracranial pressure", "n": 14}]}]}, {"id": "history-sina-mock", "subject": "history", "title": "Sina mock exam: History and Art of Medicine", "year": "Practice", "note": "25 new questions written by Sina in the style of the real exam, covering why study it, and the history of physiology, pathology, pharmacology and epidemics. One answer per question, each with a short explanation.", "questions": [{"q": "According to the course, the main point of studying the history of medicine is to:", "options": ["Understand how medicine became what it is, with intellectual humility", "Reject modern medicine", "Prove that ancient medicine was always wrong", "Memorise dates and names"], "answer": 0, "why": "Knowledge is produced inside a culture and stays open to revision."}, {"q": "Health as a balance of the four humours belongs to:", "options": ["The faith and divine will model", "Modern genetics", "The evidence and technology model", "The balance and harmony model"], "answer": 3, "why": "The three ways of explaining illness often coexisted.", "slides": [{"src": "files/slides/history-physiology/11.jpg", "lec": "History of physiology", "n": 11}]}, {"q": "'Physiology' comes from Greek and means:", "options": ["The study of nature", "The study of suffering", "The study of the body's structure", "The study of drugs"], "answer": 0, "why": "Pathology = study of suffering; pharmacology from pharmakon (drug, remedy, poison).", "slides": [{"src": "files/slides/history-physiology/04.jpg", "lec": "History of physiology", "n": 4}]}, {"q": "Vitalism holds that life is explained by:", "options": ["Peculiar life forces linked to the soul or spirit", "Physical and chemical forces only", "Statistics", "Experimentation"], "answer": 0, "why": "Mechanism (materialism) explains life by physics and chemistry.", "slides": [{"src": "files/slides/history-physiology/07.jpg", "lec": "History of physiology", "n": 7}]}, {"q": "Teleology is:", "options": ["Armchair speculation", "Pure observation", "The doctrine of purpose", "Animal experimentation"], "answer": 2, "why": "It is opposed to empiricism (observation).", "slides": [{"src": "files/slides/history-physiology/08.jpg", "lec": "History of physiology", "n": 8}]}, {"q": "In ancient physiology, the 'natural spirit' was:", "options": ["The source of motion in the brain", "Blood imbued with air in the lungs", "Blood made from food in the liver", "Bile"], "answer": 2, "why": "Vital spirit: blood with air in the lungs; animal spirit: motion, in the brain.", "slides": [{"src": "files/slides/history-physiology/13.jpg", "lec": "History of physiology", "n": 13}]}, {"q": "Galen believed that blood:", "options": ["Was made in the bone marrow", "Was formed in the liver and passed through invisible pores in the heart's septum", "Circulated in a closed loop", "Was pumped only by the lungs"], "answer": 1, "why": "Human dissection was forbidden, so he relied on animals.", "slides": [{"src": "files/slides/history-physiology/14.jpg", "lec": "History of physiology", "n": 14}]}, {"q": "Pulmonary circulation was first described by:", "options": ["Vesalius", "Galen", "Ibn al-Nafis, in the 13th century", "William Harvey"], "answer": 2, "why": "His work was unknown in Europe until translated; Servetus later described it and was burned in 1553.", "slides": [{"src": "files/slides/history-physiology/17.jpg", "lec": "History of physiology", "n": 17}]}, {"q": "Galen's physiology lasted until the 15th-16th centuries mainly because:", "options": ["Dissection confirmed it", "It suited the Church and was repeated without expressed doubt", "No one could read Greek", "It was proved by experiment"], "answer": 1, "why": "Life force = soul fitted religious doctrine.", "slides": [{"src": "files/slides/history-physiology/16.jpg", "lec": "History of physiology", "n": 16}]}, {"q": "The difference between illness and disease is that:", "options": ["They mean the same", "Illness is the patient's suffering (constant), disease is the medical idea about it (changes with knowledge)", "Disease is always visible", "Illness is only mental"], "answer": 1, "why": "Illness is patient-centred.", "slides": [{"src": "files/slides/history-pathology/14.jpg", "lec": "History of pathology", "n": 14}]}, {"q": "Ontological theories of disease see disease as:", "options": ["What the patient is (inside)", "What the patient has (an outside entity)", "A humoral imbalance only", "A divine punishment only"], "answer": 1, "why": "Physiological theories focus on the inside: what the patient is.", "slides": [{"src": "files/slides/history-pathology/12.jpg", "lec": "History of pathology", "n": 12}]}, {"q": "Autopsies for retrospective diagnosis began around the:", "options": ["20th century", "13th century", "19th century only", "5th century BC"], "answer": 1, "why": "They became widespread in medicine and law in the 19th century.", "slides": [{"src": "files/slides/history-pathology/10.jpg", "lec": "History of pathology", "n": 10}]}, {"q": "The five functions of pathology include all of the following EXCEPT:", "options": ["Identify the ailment", "Manufacture drugs", "Explain suffering", "Predict outcomes"], "answer": 1, "why": "The fifth function is to justify treatment and prove or refute an explanation.", "slides": [{"src": "files/slides/history-pathology/10.jpg", "lec": "History of pathology", "n": 10}]}, {"q": "'Primum non nocere' means:", "options": ["Like cures like", "Opposite cures opposite", "Nature heals", "First, do no harm"], "answer": 3, "why": "The first principle of pharmacology.", "slides": [{"src": "files/slides/history-pharmacology/19.jpg", "lec": "History of pharmacology", "n": 19}]}, {"q": "'Similia similibus curantur' (like cures like) is the ancestor of:", "options": ["Surgery", "Antibiotics", "Vaccination only", "Homeopathy"], "answer": 3, "why": "Contraria contrariis curantur = opposite cures opposite.", "slides": [{"src": "files/slides/history-pharmacology/16.jpg", "lec": "History of pharmacology", "n": 16}]}, {"q": "Mithridate and theriac were:", "options": ["Plague masks", "Surgical tools", "Poison antidotes", "Vaccines"], "answer": 2, "why": "Theriac kept a mystical aura until the 19th century.", "slides": [{"src": "files/slides/history-pharmacology/15.jpg", "lec": "History of pharmacology", "n": 15}]}, {"q": "In the 15th century, mercury was used to treat:", "options": ["Cholera", "Tuberculosis", "Syphilis", "Plague"], "answer": 2, "why": "The age of metals, influenced by alchemy.", "slides": [{"src": "files/slides/history-pharmacology/21.jpg", "lec": "History of pharmacology", "n": 21}]}, {"q": "Galenical pharmacology trusted mainly:", "options": ["Synthetic chemistry", "The healing power of nature", "Metals", "Radiation"], "answer": 1, "why": "About 300 medications plus diet, bloodletting, baths and exercise.", "slides": [{"src": "files/slides/history-pharmacology/19.jpg", "lec": "History of pharmacology", "n": 19}]}, {"q": "The first large wave of the Black Death reached Europe in:", "options": ["1348", "1665", "1918", "1096"], "answer": 0, "why": "It killed about 30% of Europe.", "slides": [{"src": "files/slides/history-epidemics/05.jpg", "lec": "Epidemics in history", "n": 5}]}, {"q": "The plague is caused by:", "options": ["Mycobacterium leprae", "Vibrio cholerae", "Treponema pallidum", "Yersinia pestis, carried by fleas of the black rat"], "answer": 3, "why": "Confirmed by DNA sequencing of old remains.", "slides": [{"src": "files/slides/history-epidemics/08.jpg", "lec": "Epidemics in history", "n": 8}]}, {"q": "Leprosy is the main historical example of:", "options": ["A disease cured by quarantine", "A vaccine success", "A food-borne epidemic", "Social prejudice and excessive isolation for a mildly contagious disease"], "answer": 3, "why": "Leprosaria and bells.", "slides": [{"src": "files/slides/history-epidemics/11.jpg", "lec": "Epidemics in history", "n": 11}]}, {"q": "Syphilis was called the 'French disease' after an outbreak in:", "options": ["Marseille in 1720", "Paris in 1850", "French armies in the 1490s", "French colonies in 1900"], "answer": 2, "why": "Caused by Treponema pallidum, treated with penicillin.", "slides": [{"src": "files/slides/history-epidemics/09.jpg", "lec": "Epidemics in history", "n": 9}]}, {"q": "John Snow linked cholera to drinking water in:", "options": ["1854", "1748", "1884", "1928"], "answer": 0, "why": "Vibrio cholerae was identified in 1884.", "slides": [{"src": "files/slides/history-epidemics/12.jpg", "lec": "Epidemics in history", "n": 12}]}, {"q": "Societies typically react to epidemics first with:", "options": ["Denial and delayed acceptance", "Calm", "New prevention policies", "Immediate control measures"], "answer": 0, "why": "Then panic and flight, explanations, control measures and finally return to normal life.", "slides": [{"src": "files/slides/history-epidemics/04.jpg", "lec": "Epidemics in history", "n": 4}]}, {"q": "Michael Servetus was burned alive in 1553 for:", "options": ["Selling poisons", "His theological views (his book also described pulmonary circulation)", "Describing the circulation of blood", "Performing autopsies"], "answer": 1, "why": "His description of pulmonary circulation appeared in a theological work.", "slides": [{"src": "files/slides/history-physiology/17.jpg", "lec": "History of physiology", "n": 17}]}]}]);
